const NODE_FLAG_JSDOC: u32 = 1 << 22;
const NODE_FLAG_HAS_ERROR: u32 = 1 << 15;
const MAX_INTERFACE_PROPERTY_HERITAGE_DEPTH: usize = 16;

/// Reads a source or symbol key through the receiver's validated member table.
/// Generic references share the caller's session when a property needs its type.
pub(super) fn resolve_object_property_by_key(
    store: &mut CanonicalTypeMapperStore,
    global_types: Option<&CanonicalGlobalTypes>,
    receiver: TypeId,
    name: EscapedNameRef<'_>,
    session: &mut InstantiationSession,
) -> Result<Option<ResolvedOwnProperty>, RelationUnavailable> {
    resolve_object_property_by_key_with_alias_operand(
        store,
        global_types,
        receiver,
        name,
        session,
        None,
    )
}

/// The optional input proves a closed source object before the ordinary table read.
pub(super) fn resolve_object_property_by_key_with_alias_operand(
    store: &mut CanonicalTypeMapperStore,
    global_types: Option<&CanonicalGlobalTypes>,
    receiver: TypeId,
    name: EscapedNameRef<'_>,
    session: &mut InstantiationSession,
    operand: Option<(&SourceAliasOperandGraph, NodeRef)>,
) -> Result<Option<ResolvedOwnProperty>, RelationUnavailable> {
    if let Some((graph, node)) = operand {
        return property_from_source_alias_members(
            store,
            graph,
            node,
            receiver,
            name,
            global_types.map(CanonicalArrayTargets::from_global_types),
        );
    }
    if let Some(members) = validated_module_value_members(store, receiver)? {
        return property_from_module_value_members(store, members, name);
    }
    if source_property_object_projection(store, receiver)?.is_some() {
        let members = match validate_property_object_alias_members_with_array_targets(
            store,
            receiver,
            global_types.map(CanonicalArrayTargets::from_global_types),
        )? {
            Some(members) => members,
            None => resolve_property_object_alias_members_with_array_targets(
                store,
                receiver,
                global_types.map(CanonicalArrayTargets::from_global_types),
            )?,
        };
        let Some(property) = members
            .members
            .and_then(|members| store.symbol_table(members))
            .and_then(|members| members.get(name))
        else {
            return Ok(None);
        };
        let type_ = store
            .value_symbol_links(property)
            .and_then(|links| links.resolved_type)
            .ok_or(RelationUnavailable::UnresolvedPropertyType(property))?;
        let record = store
            .symbol(property)
            .ok_or(RelationUnavailable::Symbol(property))?;
        return Ok(Some(ResolvedOwnProperty {
            symbol: property,
            type_,
            optional: record.flags().contains(SymbolFlags::OPTIONAL),
            readonly: record.check_flags().contains(CheckFlags::READONLY),
        }));
    }
    if let Some(selected) =
        super::declared_values::selected_declared_property(store, receiver, name)?
    {
        return match selected {
            super::declared_values::SelectedDeclaredProperty::Missing => Ok(None),
            super::declared_values::SelectedDeclaredProperty::Unresolved(symbol) => {
                Err(RelationUnavailable::UnresolvedPropertyType(symbol))
            }
            super::declared_values::SelectedDeclaredProperty::Resolved(property) => {
                Ok(Some(property))
            }
        };
    }
    let record = store
        .type_payload(receiver)
        .ok_or(RelationUnavailable::Type(receiver))?;
    if matches!(record.data(), TypeData::Object(_))
        && let Some(owner) = record.symbol().filter(|owner| {
            store
                .symbol(*owner)
                .is_some_and(|owner| owner.flags().contains(SymbolFlags::CLASS))
        })
    {
        if super::classes::authenticated_class_constructor_value(store, owner)
            .is_none_or(|(value, _)| value != receiver)
        {
            return Err(RelationUnavailable::InvalidStructuredMembers(receiver));
        }
        return property_from_validated_members(store, receiver, name);
    }
    let target = match record.data() {
        TypeData::TypeReference(reference) => reference.object.target,
        TypeData::Interface(interface)
            if record.object_flags().contains(ObjectFlags::REFERENCE)
                && validate_nongeneric_interface_argument_origin(store, receiver).is_err() =>
        {
            interface.reference.object.target
        }
        _ => None,
    };
    let inherited_reference = if store
        .direct_interface_heritage_provenance(receiver)
        .is_some()
    {
        store
            .type_payload(receiver)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.members)
            .and_then(|members| store.symbol_table(members))
            .and_then(|members| members.get(name))
            .filter(|property| {
                store.symbol(*property).is_some_and(|record| {
                    record.flags().contains(SymbolFlags::TRANSIENT)
                        && record.check_flags().contains(CheckFlags::INSTANTIATED)
                })
            })
            .map(|property| {
                super::structured_members::inherited_generic_property_reference(
                    store,
                    receiver,
                    property,
                    global_types.map(CanonicalArrayTargets::from_global_types),
                )
                .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))
            })
            .transpose()?
    } else {
        None
    };
    let reference = inherited_reference.or_else(|| {
        target
            .filter(|target| {
                store.type_payload(*target).is_some_and(|target| {
                    matches!(target.data(), TypeData::Interface(_))
                        && (!target.object_flags().contains(ObjectFlags::CLASS)
                            || matches!(record.data(), TypeData::TypeReference(_)))
                })
            })
            .map(|_| receiver)
    });
    if let Some(reference) = reference {
        return resolve_property_with_array_targets_and_session(
            store,
            reference,
            name,
            global_types.map(CanonicalArrayTargets::from_global_types),
            session,
        )
        .map(|property| {
            property.map(|property| ResolvedOwnProperty {
                symbol: property.symbol(),
                type_: property.type_id(),
                optional: property.is_optional(),
                readonly: property.is_readonly(),
            })
        })
        .map_err(|error| match error {
            GenericInterfaceMemberError::UnsupportedTarget(type_)
            | GenericInterfaceMemberError::UnsupportedPropertyType(type_) => {
                RelationUnavailable::UnsupportedStructuredType(type_)
            }
            GenericInterfaceMemberError::UnsupportedMember(symbol) => {
                RelationUnavailable::UnsupportedProperty(symbol)
            }
            GenericInterfaceMemberError::Capacity(type_) => {
                RelationUnavailable::UnionValidationCapacity(type_)
            }
            GenericInterfaceMemberError::Reference(_)
            | GenericInterfaceMemberError::InvalidTarget(_)
            | GenericInterfaceMemberError::InvalidMember(_)
            | GenericInterfaceMemberError::InvalidCachedMembers(_)
            | GenericInterfaceMemberError::InvalidCachedProperty(_) => {
                RelationUnavailable::InvalidStructuredMembers(receiver)
            }
        });
    }
    match validate_stored_declared_call_set(store, receiver) {
        StoredDeclaredCallSetValidation::Valid(_) => {
            property_from_validated_members(store, receiver, name)
        }
        StoredDeclaredCallSetValidation::Malformed => {
            Err(RelationUnavailable::InvalidStructuredMembers(receiver))
        }
        StoredDeclaredCallSetValidation::NotDeclaredCallSet => {
            if let Some(property) = super::structured_members::validated_interface_property_by_key(
                store,
                receiver,
                name,
                global_types.map(CanonicalArrayTargets::from_global_types),
            ) {
                return Ok(property);
            }
            if store.type_payload(receiver).is_some_and(|record| {
                matches!(record.data(), TypeData::Interface(_))
                    && record
                        .symbol()
                        .and_then(|owner| store.source_computed_member_count(owner))
                        .is_some_and(|count| count != 0)
            }) {
                return Err(RelationUnavailable::InvalidStructuredMembers(receiver));
            }
            store.resolved_own_property_by_key_with_context(receiver, name, global_types, session)
        }
    }
}

pub(super) fn property_from_source_alias_members(
    store: &CanonicalTypeMapperStore,
    graph: &SourceAliasOperandGraph,
    node: NodeRef,
    receiver: TypeId,
    name: EscapedNameRef<'_>,
    array_targets: Option<CanonicalArrayTargets>,
) -> Result<Option<ResolvedOwnProperty>, RelationUnavailable> {
    graph.validate_closed_object(store, node, receiver, array_targets)?;
    property_from_validated_members(store, receiver, name)
}

pub(super) fn property_from_module_value_members(
    store: &CanonicalTypeMapperStore,
    members: ModuleValueMembers<'_>,
    name: EscapedNameRef<'_>,
) -> Result<Option<ResolvedOwnProperty>, RelationUnavailable> {
    let property = members
        .members()
        .and_then(|table| store.symbol_table(table))
        .and_then(|table| table.get(name));
    if property.is_none_or(|property| !members.properties().contains(&property)) {
        // The binder keeps type-only exports in the same table as values.
        return Ok(None);
    }
    property_from_validated_members(store, members.type_(), name).map(|property| {
        property.map(|mut property| {
            property.readonly |= members.is_readonly(property.symbol);
            property
        })
    })
}

fn property_from_validated_members(
    store: &CanonicalTypeMapperStore,
    receiver: TypeId,
    name: EscapedNameRef<'_>,
) -> Result<Option<ResolvedOwnProperty>, RelationUnavailable> {
    let structured = store
        .type_payload(receiver)
        .and_then(|record| record.data().structured())
        .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
    let Some(members) = structured.members else {
        return Ok(None);
    };
    let Some(symbol) = store
        .symbol_table(members)
        .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?
        .get(name)
    else {
        return Ok(None);
    };
    if !structured
        .properties
        .as_deref()
        .unwrap_or_default()
        .contains(&symbol)
    {
        return Err(RelationUnavailable::InvalidStructuredMembers(receiver));
    }
    let property = store
        .symbol(symbol)
        .ok_or(RelationUnavailable::Symbol(symbol))?;
    let type_ = store
        .value_symbol_links(symbol)
        .and_then(|links| links.resolved_type)
        .ok_or(RelationUnavailable::UnresolvedPropertyType(symbol))?;
    Ok(Some(ResolvedOwnProperty {
        symbol,
        type_,
        optional: property.flags().contains(SymbolFlags::OPTIONAL),
        readonly: property.check_flags().contains(CheckFlags::READONLY),
    }))
}

#[derive(Clone, Debug)]
struct SourceMemberName {
    declaration: NodeRef,
    symbol: SemanticSymbolId,
    name: Option<EscapedName>,
    computed: Option<PlannedComputedMemberKey>,
}

/// Resolves one source member without preparing sibling type annotations.
/// Alias instances return their source-owned proxy symbol.
/// Use this result for type reads, not union-property or member-table publication.
#[cfg_attr(not(test), allow(dead_code))]
#[allow(clippy::too_many_arguments)] // Keep the source query's diagnostics and instantiation limits.
pub(super) fn resolve_object_property_by_key_with_source(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    receiver: TypeId,
    name: EscapedNameRef<'_>,
    session: &mut InstantiationSession,
    diagnostics: &mut CanonicalCheckerDiagnostics,
) -> Result<Option<ResolvedOwnProperty>, SourceCheckError> {
    let conditional_mapped = store.type_payload(receiver).is_some_and(|record| {
        matches!(record.data(), TypeData::Mapped(mapped)
        if mapped.template_type.is_some_and(|template| {
            matches!(store.type_payload(template).map(TypeRecord::data),
                Some(TypeData::Conditional(_)))
        }))
    });
    if conditional_mapped {
        return CanonicalTypeQuery::new_with_global_types_and_session(
            store,
            host,
            global_types,
            options,
            session,
            diagnostics,
        )?
        .get_type_of_mapped_property(receiver, name)
        .map(|property| {
            property.map(|property| ResolvedOwnProperty {
                symbol: property.symbol(),
                type_: property.type_id(),
                optional: property.is_optional(),
                readonly: property.is_readonly(),
            })
        })
        .map_err(Into::into);
    }
    if source_property_object_projection(store, receiver)?.is_some() {
        let members = match validate_property_object_alias_members_with_array_targets(
            store,
            receiver,
            Some(CanonicalArrayTargets::from_global_types(global_types)),
        )? {
            Some(members) => members,
            None => resolve_property_object_alias_members_with_array_targets(
                store,
                receiver,
                Some(CanonicalArrayTargets::from_global_types(global_types)),
            )?,
        };
        let Some(property) = members
            .members
            .and_then(|members| store.symbol_table(members))
            .and_then(|members| members.get(name))
        else {
            return Ok(None);
        };
        let type_ = demand_property_object_alias_property(
            store,
            host,
            global_types,
            options,
            session,
            diagnostics,
            receiver,
            property,
        )?;
        let record = store
            .symbol(property)
            .ok_or(RelationUnavailable::Symbol(property))?;
        return Ok(Some(ResolvedOwnProperty {
            symbol: property,
            type_,
            optional: record.flags().contains(SymbolFlags::OPTIONAL),
            readonly: record.check_flags().contains(CheckFlags::READONLY),
        }));
    }
    if let Some(tuple) = store
        .canonical_tuple_shape(receiver)
        .map_err(|_| RelationUnavailable::InvalidStructuredMembers(receiver))?
    {
        if tuple
            .combined_flags()
            .intersects(super::signatures::ElementFlags::VARIADIC)
            || name
                .as_utf8()
                .is_some_and(|name| name == "length" || name.parse::<u32>().is_ok())
        {
            return Err(RelationUnavailable::UnsupportedStructuredType(receiver).into());
        }
        let readonly = tuple.is_readonly();
        let elements = tuple.element_types().to_vec();
        let array_target = if readonly {
            global_types.readonly_array_type
        } else {
            global_types.array_type
        };
        let target = store
            .canonical_array_reference(global_types, array_target)?
            .ok_or(RelationUnavailable::InvalidStructuredMembers(array_target))?;
        let target_record = store
            .type_payload(target.base_type)
            .ok_or(RelationUnavailable::InvalidStructuredMembers(array_target))?;
        let TypeData::Interface(interface) = target_record.data() else {
            return Err(RelationUnavailable::InvalidStructuredMembers(array_target).into());
        };
        if interface.declared_members_resolved {
            validate_generic_interface_members(
                store,
                array_target,
                Some(CanonicalArrayTargets::from_global_types(global_types)),
            )
            .map_err(|error| source_generic_member_error(array_target, &error))?;
        } else {
            if !valid_cold_declared_member_cache(interface) {
                return Err(RelationUnavailable::InvalidStructuredMembers(array_target).into());
            }
            let owner = target_record
                .symbol()
                .ok_or(RelationUnavailable::InvalidStructuredMembers(array_target))?;
            if preflight_source_member_selection(
                store,
                host,
                global_types,
                options,
                owner,
                array_target,
                name,
                session,
                diagnostics,
            )?
            .is_none()
            {
                return Ok(None);
            }
        }
        let element = store.expression_union_type_with_global_types(
            global_types,
            &elements,
            UnionReduction::Literal,
        )?;
        let array = store.create_canonical_array_type(global_types, element, readonly)?;
        return resolve_object_property_by_key_with_source(
            store,
            host,
            global_types,
            options,
            array,
            name,
            session,
            diagnostics,
        );
    }

    let array = store.canonical_array_reference(global_types, receiver)?;
    let receiver = array.map_or(receiver, |array| array.base_type);
    let record = store
        .type_payload(receiver)
        .ok_or(RelationUnavailable::Type(receiver))?;
    let source_class_target = match record.data() {
        TypeData::TypeReference(reference) => reference.object.target.filter(|target| {
            store.source_class_provenance(*target).is_some()
                && store
                    .type_payload(*target)
                    .is_some_and(|record| record.object_flags().contains(ObjectFlags::CLASS))
        }),
        _ => None,
    };
    if source_class_target.is_some() {
        return resolve_instantiated_object_property_by_key_with_source(
            store,
            host,
            global_types,
            options,
            receiver,
            name,
            session,
            diagnostics,
        );
    }
    if store.source_class_provenance(receiver).is_some()
        && matches!(record.data(), TypeData::Interface(class)
            if class.reference.resolved_type_arguments.as_deref() == Some(&[]))
    {
        return resolve_completed_class_origin_property_by_key_with_source(
            store,
            host,
            global_types,
            options,
            receiver,
            name,
            session,
            diagnostics,
        );
    }
    let nongeneric_origin = matches!(record.data(), TypeData::Interface(_))
        && validate_nongeneric_interface_argument_origin(store, receiver).is_ok();
    let generic = match record.data() {
        TypeData::TypeReference(_) => true,
        TypeData::Interface(_) => {
            record.object_flags().contains(ObjectFlags::REFERENCE) && !nongeneric_origin
        }
        _ => false,
    };
    if record
        .object_flags()
        .contains(ObjectFlags::MEMBERS_RESOLVED)
    {
        let target = match record.data() {
            TypeData::TypeReference(reference) => reference.object.target,
            TypeData::Interface(interface) if generic => interface.reference.object.target,
            _ => None,
        };
        if target.is_some_and(|target| {
            store.type_payload(target).is_some_and(|record| {
                matches!(record.data(), TypeData::Interface(_))
                    && !record.object_flags().contains(ObjectFlags::CLASS)
            })
        }) {
            return resolve_instantiated_object_property_by_key_with_source(
                store,
                host,
                global_types,
                options,
                receiver,
                name,
                session,
                diagnostics,
            );
        }
        return resolve_object_property_by_key(store, Some(global_types), receiver, name, session)
            .map_err(Into::into);
    }
    let (owner, mapper_sources, mapper_targets) = if generic {
        let reference = validate_direct_generic_reference(store, receiver)
            .map_err(|_| RelationUnavailable::InvalidStructuredMembers(receiver))?;
        let target = store
            .type_payload(reference.target)
            .ok_or(RelationUnavailable::Type(reference.target))?;
        let TypeData::Interface(interface) = target.data() else {
            return Err(RelationUnavailable::UnsupportedStructuredType(receiver).into());
        };
        if target.object_flags().contains(ObjectFlags::CLASS) {
            return resolve_object_property_by_key(
                store,
                Some(global_types),
                receiver,
                name,
                session,
            )
            .map_err(Into::into);
        }
        if interface.declared_members_resolved {
            return resolve_instantiated_object_property_by_key_with_source(
                store,
                host,
                global_types,
                options,
                receiver,
                name,
                session,
                diagnostics,
            );
        }
        if record
            .data()
            .structured()
            .is_none_or(|members| members != &StructuredTypeData::default())
            || !valid_cold_declared_member_cache(interface)
        {
            return Err(RelationUnavailable::InvalidStructuredMembers(receiver).into());
        }
        let parameters = interface
            .reference
            .resolved_type_arguments
            .as_deref()
            .filter(|parameters| !parameters.is_empty())
            .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
        let this_type = interface
            .this_type
            .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
        let sources = parameters
            .iter()
            .copied()
            .chain([this_type])
            .collect::<Vec<_>>();
        let targets = reference
            .type_arguments
            .iter()
            .copied()
            .chain([receiver])
            .collect::<Vec<_>>();
        (
            target
                .symbol()
                .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?,
            sources,
            targets,
        )
    } else {
        let owner = record
            .symbol()
            .ok_or(RelationUnavailable::UnsupportedStructuredType(receiver))?;
        if !matches!(record.data(), TypeData::Interface(_) | TypeData::Object(_))
            || store.symbol(owner).is_none_or(|owner| {
                !owner.flags().contains(SymbolFlags::INTERFACE)
                    && owner.flags() != SymbolFlags::TYPE_LITERAL
            })
        {
            return resolve_object_property_by_key(
                store,
                Some(global_types),
                receiver,
                name,
                session,
            )
            .map_err(Into::into);
        }
        match record.data() {
            TypeData::Interface(interface) => {
                if super::declared::cached_interface_type(store, owner)? != Some(receiver)
                    || !valid_cold_declared_member_cache(interface)
                    || interface.resolved_base_types.is_some()
                    || interface.resolved_base_constructor_type.is_some()
                {
                    return Err(RelationUnavailable::InvalidStructuredMembers(receiver).into());
                }
            }
            TypeData::Object(object) => {
                let declaration = store
                    .symbol(owner)
                    .and_then(ts_binder::semantic::Symbol::declarations)
                    .and_then(|declarations| {
                        declarations
                            .first()
                            .copied()
                            .filter(|_| declarations.len() == 1)
                    })
                    .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
                if store
                    .type_node_links(declaration)
                    .and_then(|links| links.resolved_type)
                    != Some(receiver)
                    || record.object_flags() != ObjectFlags::ANONYMOUS
                    || object.target.is_some()
                    || object.mapper.is_some()
                    || object.instantiations != TypeCacheState::Unallocated
                    || object.structured != StructuredTypeData::default()
                {
                    return Err(RelationUnavailable::InvalidStructuredMembers(receiver).into());
                }
            }
            _ => {}
        }
        (owner, Vec::new(), Vec::new())
    };
    let Some(symbol) = preflight_source_member_selection(
        store,
        host,
        global_types,
        options,
        owner,
        receiver,
        name,
        session,
        diagnostics,
    )?
    else {
        return Ok(None);
    };
    let method = store
        .symbol(symbol)
        .ok_or(RelationUnavailable::Symbol(symbol))?
        .flags()
        .contains(SymbolFlags::METHOD);
    let mut query = CanonicalTypeQuery::new_with_global_types_and_session(
        store,
        host,
        global_types,
        options,
        session,
        diagnostics,
    )?;
    let template = if method {
        query.get_type_of_interface_method(symbol)?
    } else {
        query.get_type_of_declared_value(symbol)?
    };
    let symbol = store
        .late_bound_links(symbol)
        .and_then(|links| links.late_symbol)
        .unwrap_or(symbol);
    let property = store
        .symbol(symbol)
        .ok_or(RelationUnavailable::Symbol(symbol))?;
    if property.name() != name || store.get_parent_of_symbol(symbol) != Some(owner) {
        return Err(RelationUnavailable::InvalidStructuredMembers(receiver).into());
    }
    let optional = property.flags().contains(SymbolFlags::OPTIONAL);
    let readonly = property.check_flags().contains(CheckFlags::READONLY);
    let type_ = if mapper_sources.is_empty() {
        template
    } else if method {
        CanonicalTypeQuery::new_with_global_types_and_session(
            store,
            host,
            global_types,
            options,
            session,
            diagnostics,
        )?
        .get_type_of_instantiated_interface_method(receiver, symbol)?
    } else if array.is_some() && store.type_has_function_type_provenance(template) {
        instantiate_published_generic_array_property_callable(store, global_types, receiver, symbol)
            .map_err(|error| source_generic_member_error(receiver, &error))?
    } else {
        super::instantiate::instantiate_type_with_vector_and_session(
            store,
            template,
            &mapper_sources,
            &mapper_targets,
            Some(CanonicalArrayTargets::from_global_types(global_types)),
            session,
        )
        .map_err(|error| {
            source_generic_member_error(receiver, &property_instantiation_error(template, &error))
        })?
    };
    Ok(Some(ResolvedOwnProperty {
        symbol,
        type_,
        optional,
        readonly,
    }))
}

/// Resolves a selected array data property while retaining its source symbol.
/// A receiver proxy supplies the mapped type, not the property-access identity.
#[allow(clippy::too_many_arguments)]
pub(super) fn resolve_source_array_property(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    receiver: TypeId,
    name: EscapedNameRef<'_>,
    source_symbol: SemanticSymbolId,
    session: &mut InstantiationSession,
    diagnostics: &mut CanonicalCheckerDiagnostics,
) -> Result<ResolvedOwnProperty, SourceCheckError> {
    let mut staged = CanonicalCheckerDiagnostics::default();
    let result = (|| {
        let array = store
            .canonical_array_reference(global_types, receiver)?
            .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
        let target = if array.readonly {
            global_types.readonly_array_type
        } else {
            global_types.array_type
        };
        let owner = store
            .type_payload(target)
            .and_then(TypeRecord::symbol)
            .and_then(|symbol| store.get_merged_symbol(symbol))
            .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
        let source = store
            .symbol(source_symbol)
            .ok_or(RelationUnavailable::Symbol(source_symbol))?;
        if source.name() != name
            || store.get_parent_of_symbol(source_symbol) != Some(owner)
            || source.flags() != SymbolFlags::PROPERTY
                && source.flags() != (SymbolFlags::PROPERTY | SymbolFlags::OPTIONAL)
            || store
                .symbol(owner)
                .and_then(|owner| owner.members())
                .and_then(|members| store.symbol_table(members))
                .and_then(|members| members.get(name))
                .and_then(|symbol| store.get_merged_symbol(symbol))
                != Some(source_symbol)
        {
            return Err(RelationUnavailable::InvalidStructuredMembers(receiver).into());
        }
        let optional = source.flags().contains(SymbolFlags::OPTIONAL);
        let readonly = source.check_flags().contains(CheckFlags::READONLY);
        let resolved = resolve_object_property_by_key_with_source(
            store,
            host,
            global_types,
            options,
            receiver,
            name,
            session,
            &mut staged,
        )?
        .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
        if resolved.symbol != source_symbol {
            let members = validate_generic_interface_members(
                store,
                array.base_type,
                Some(CanonicalArrayTargets::from_global_types(global_types)),
            )
            .map_err(|error| source_generic_member_error(receiver, &error))?
            .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
            if members
                .members()
                .and_then(|members| store.symbol_table(members))
                .and_then(|members| members.get(name))
                != Some(resolved.symbol)
                || store
                    .value_symbol_links(resolved.symbol)
                    .and_then(|links| links.target)
                    != Some(source_symbol)
            {
                return Err(RelationUnavailable::InvalidStructuredMembers(receiver).into());
            }
        }
        if resolved.optional != optional || resolved.readonly != readonly {
            return Err(RelationUnavailable::InvalidStructuredMembers(receiver).into());
        }
        Ok(ResolvedOwnProperty {
            symbol: source_symbol,
            type_: resolved.type_,
            optional,
            readonly,
        })
    })();
    super::source::merge_retry_diagnostics(diagnostics, staged);
    result
}

#[allow(clippy::too_many_arguments)] // Keep the source host and limits with the selected proxy.
fn resolve_completed_class_origin_property_by_key_with_source(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    receiver: TypeId,
    name: EscapedNameRef<'_>,
    session: &mut InstantiationSession,
    diagnostics: &mut CanonicalCheckerDiagnostics,
) -> Result<Option<ResolvedOwnProperty>, SourceCheckError> {
    let invalid = || RelationUnavailable::InvalidStructuredMembers(receiver);
    let members = super::classes::completed_source_class_receiver_members(store, receiver)
        .map_err(|_| invalid())?
        .ok_or_else(invalid)?;
    let Some(table) = members.instance_members() else {
        return Ok(None);
    };
    let Some(symbol) = store.symbol_table(table).ok_or_else(invalid)?.get(name) else {
        return Ok(None);
    };
    if !members.instance_properties().contains(&symbol) {
        return Err(invalid().into());
    }
    let record = store.symbol(symbol).ok_or_else(invalid)?;
    let optional = record.flags().contains(SymbolFlags::OPTIONAL);
    let readonly = record.check_flags().contains(CheckFlags::READONLY);
    if super::instantiated_members::completed_source_class_origin_member_mapping(
        store,
        receiver,
        symbol,
        Some(CanonicalArrayTargets::from_global_types(global_types)),
    )
    .map_err(|error| source_generic_member_error(receiver, &error))?
    .is_none()
    {
        return resolve_object_property_by_key(store, Some(global_types), receiver, name, session)
            .map_err(Into::into);
    }
    let type_ = CanonicalTypeQuery::new_with_global_types_and_session(
        store,
        host,
        global_types,
        options,
        session,
        diagnostics,
    )?
    .get_type_of_instantiated_interface_property(receiver, symbol)?;
    Ok(Some(ResolvedOwnProperty {
        symbol,
        type_,
        optional,
        readonly,
    }))
}

#[allow(clippy::too_many_arguments)] // Keep the source host and limits with the selected proxy.
fn resolve_instantiated_object_property_by_key_with_source(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    receiver: TypeId,
    name: EscapedNameRef<'_>,
    session: &mut InstantiationSession,
    diagnostics: &mut CanonicalCheckerDiagnostics,
) -> Result<Option<ResolvedOwnProperty>, SourceCheckError> {
    if store
        .direct_interface_heritage_provenance(receiver)
        .is_some()
    {
        return resolve_object_property_by_key(store, Some(global_types), receiver, name, session)
            .map_err(Into::into);
    }
    let members = resolve_members_with_array_targets_and_session(
        store,
        receiver,
        Some(CanonicalArrayTargets::from_global_types(global_types)),
        session,
    )
    .map_err(|error| source_generic_member_error(receiver, &error))?;
    let Some(table) = members.members() else {
        return Ok(None);
    };
    let table = store
        .symbol_table(table)
        .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
    let Some(symbol) = table.get(name) else {
        return Ok(None);
    };
    let record = store
        .symbol(symbol)
        .ok_or(RelationUnavailable::InvalidStructuredMembers(receiver))?;
    let optional = record.flags().contains(SymbolFlags::OPTIONAL);
    let readonly = record.check_flags().contains(CheckFlags::READONLY);
    let source_class = store.type_payload(receiver).is_some_and(|record| {
        matches!(record.data(), TypeData::TypeReference(reference)
        if reference.object.target.is_some_and(|target| {
            store.source_class_provenance(target).is_some()
        }))
    });
    let type_ = if record.flags().contains(SymbolFlags::METHOD) || source_class {
        CanonicalTypeQuery::new_with_global_types_and_session(
            store,
            host,
            global_types,
            options,
            session,
            diagnostics,
        )?
        .get_type_of_instantiated_interface_property(receiver, symbol)?
    } else {
        demand_instantiated_property_type(
            store,
            receiver,
            symbol,
            Some(CanonicalArrayTargets::from_global_types(global_types)),
            session,
        )
        .map_err(|error| source_generic_member_error(receiver, &error))?
    };
    Ok(Some(ResolvedOwnProperty {
        symbol,
        type_,
        optional,
        readonly,
    }))
}

fn valid_cold_declared_member_cache(interface: &InterfaceTypeData) -> bool {
    !interface.declared_members_resolved
        && interface.declared_members.is_none()
        && interface.declared_call_signatures.is_none()
        && interface.declared_construct_signatures.is_none()
        && interface.declared_index_infos.is_none()
        && interface.reference.object.structured == StructuredTypeData::default()
}

use super::{
    DeclaredTypeError, DeclaredTypeUnavailable,
    conditional_types::ConditionalSourceQueryRequest,
    interface_heritage::{
        SourceInterfaceAliasBaseRequest, SourceInterfaceAliasBaseState,
        SourceInterfaceHeritageHeader, SourceInterfaceHeritageQueryContext,
    },
};

/// A query-local proof for the exact read type. It does not publish member caches.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(super) struct SourceInterfaceConditionHeader {
    condition_type: TypeId,
    receiver: TypeId,
    global_object_type: TypeId,
    _owners: Vec<SourceInterfaceConditionOwner>,
}

impl SourceInterfaceConditionHeader {
    pub(super) const fn condition_type(&self) -> TypeId {
        self.condition_type
    }

    #[cfg_attr(not(test), allow(dead_code))]
    pub(super) const fn receiver(&self) -> TypeId {
        self.receiver
    }

    #[cfg_attr(not(test), allow(dead_code))]
    pub(super) const fn global_object_type(&self) -> TypeId {
        self.global_object_type
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(super) enum SourceInterfaceConditionPlan {
    Ready(SourceInterfaceConditionHeader),
    Pending(Vec<SourceInterfaceConditionRequest>),
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(super) enum SourceInterfaceConditionRequest {
    InterfaceIdentity {
        symbol: SemanticSymbolId,
    },
    HeritageHeader {
        receiver: TypeId,
        header: SourceInterfaceHeritageHeader,
    },
    AliasBase {
        request: SourceInterfaceAliasBaseRequest,
        conditional: Option<ConditionalSourceQueryRequest>,
    },
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct SourceInterfaceConditionOwner {
    type_: TypeId,
    symbol: SemanticSymbolId,
    declarations: Vec<NodeRef>,
    members: Option<SymbolTableId>,
    names: Vec<(NodeRef, SemanticSymbolId, EscapedName)>,
    bases: Vec<(SemanticSymbolId, TypeId)>,
    edges: Vec<TypeId>,
}

#[derive(Default)]
struct SourceInterfaceConditionWalk {
    active: HashSet<TypeId>,
    complete: HashSet<TypeId>,
    owners: Vec<SourceInterfaceConditionOwner>,
    pending: Vec<SourceInterfaceConditionRequest>,
    deferred_complete: bool,
}

enum SourceInterfaceConditionBase {
    Pending,
    Ineligible,
    Ready(TypeId),
}

fn source_interface_condition_error(symbol: SemanticSymbolId, type_: TypeId) -> DeclaredTypeError {
    DeclaredTypeUnavailable::InvalidCachedDeclaredType {
        symbol,
        declared_type: type_,
    }
    .into()
}

fn source_condition_graph_error(
    error: super::bootstrap::LiteralTypeCacheError,
) -> DeclaredTypeError {
    use super::{TypeNodeUnavailable, bootstrap::LiteralTypeCacheError};
    match error {
        LiteralTypeCacheError::BootstrapUninitialized => {
            DeclaredTypeUnavailable::IntrinsicBootstrapNotInitialized.into()
        }
        LiteralTypeCacheError::ArrayType { type_, .. } => {
            TypeNodeUnavailable::InvalidCachedArrayType(type_).into()
        }
        LiteralTypeCacheError::UnsupportedUnionConstituent(type_) => {
            TypeNodeUnavailable::UnsupportedUnionConstituentType(type_).into()
        }
        LiteralTypeCacheError::InvalidCachedUnion(type_) => {
            TypeNodeUnavailable::InvalidCachedUnionType(type_).into()
        }
        LiteralTypeCacheError::InvalidCachedLiteral(type_) => {
            TypeNodeUnavailable::InvalidCachedLiteralType(type_).into()
        }
        LiteralTypeCacheError::InvalidUnionAlias(symbol) => {
            TypeNodeUnavailable::InvalidUnionAlias(symbol).into()
        }
        LiteralTypeCacheError::InvalidPreparedQuery => {
            TypeNodeUnavailable::InvalidPreparedTypeQuery.into()
        }
        LiteralTypeCacheError::InvalidValue => TypeNodeUnavailable::InvalidLiteralCacheValue.into(),
        LiteralTypeCacheError::Capacity => TypeNodeUnavailable::LiteralTypeCapacity.into(),
    }
}

/// Retains the nullable input and asks only for real base identities or alias results.
#[allow(clippy::too_many_lines)] // Eligibility, Object authority and graph validation are one proof.
pub(super) fn plan_source_interface_condition_header(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    condition_type: TypeId,
    globals: &CanonicalGlobalTypes,
    array_targets: Option<CanonicalArrayTargets>,
    query: Option<&SourceInterfaceHeritageQueryContext<'_>>,
) -> Result<Option<SourceInterfaceConditionPlan>, DeclaredTypeError> {
    let bootstrap = store
        .intrinsic_bootstrap()
        .ok_or(DeclaredTypeUnavailable::IntrinsicBootstrapNotInitialized)?;
    let invalid_input = || {
        DeclaredTypeError::from(super::TypeNodeUnavailable::InvalidCachedUnionType(
            condition_type,
        ))
    };
    let record = store
        .type_payload(condition_type)
        .ok_or_else(invalid_input)?;
    let inputs = match record.data() {
        TypeData::Interface(_) => vec![condition_type],
        TypeData::Union(union) => union.union.types.clone(),
        _ => return Ok(None),
    };
    let mut receiver = None;
    for &type_ in &inputs {
        if [
            bootstrap.null_type,
            bootstrap.undefined_type,
            bootstrap.missing_type,
        ]
        .contains(&type_)
        {
            continue;
        }
        let record = store.type_payload(type_).ok_or_else(invalid_input)?;
        if !matches!(record.data(), TypeData::Interface(_)) || receiver.replace(type_).is_some() {
            return Ok(None);
        }
    }
    let Some(receiver) = receiver else {
        return Ok(None);
    };

    // A missing Object library is not an empty semantic property fallback.
    let mut resolver_host = host.name_resolver_host(store)?;
    let object_symbol = ts_binder::resolve_global_name(
        store.symbol_store(),
        &mut resolver_host,
        "Object",
        SymbolFlags::TYPE,
        None,
        false,
        false,
    )?;
    let Some(object_symbol) = object_symbol else {
        return if globals.object_type == bootstrap.empty_object_type {
            Ok(None)
        } else {
            Err(invalid_input())
        };
    };
    let object_symbol = store
        .get_merged_symbol(object_symbol)
        .ok_or_else(invalid_input)?;
    let invalid_object = || source_interface_condition_error(object_symbol, globals.object_type);
    if store
        .type_payload(globals.object_type)
        .and_then(TypeRecord::symbol)
        != Some(object_symbol)
        || super::declared::cached_interface_type(store, object_symbol)?
            != Some(globals.object_type)
        || query
            .is_some_and(|query| query.globals != globals || query.array_targets != array_targets)
    {
        return Err(invalid_object());
    }
    if matches!(record.data(), TypeData::Union(_)) {
        store
            .validate_canonical_union_metadata(condition_type, &inputs)
            .map_err(|_| invalid_input())?;
    }
    for &type_ in inputs.iter().filter(|type_| **type_ != receiver) {
        store
            .validate_union_constituent(type_)
            .map_err(|_| invalid_input())?;
    }
    let mut walk = SourceInterfaceConditionWalk::default();
    if !source_interface_condition_owner(store, host, receiver, array_targets, query, &mut walk)?
        || !source_interface_condition_owner(
            store,
            host,
            globals.object_type,
            array_targets,
            query,
            &mut walk,
        )?
    {
        return Ok(None);
    }
    if walk.deferred_complete {
        // A complete cache still needs the current operational alias proof.
        // Pending grants neither member absence nor a complete graph proof.
        return Ok(Some(SourceInterfaceConditionPlan::Pending(walk.pending)));
    }
    // These edges have already passed the source and current base-cache readers.
    // The existing Array walk keeps its visited set across the whole read graph.
    let source_edges = |type_: TypeId| {
        Ok(walk
            .owners
            .iter()
            .find(|owner| owner.type_ == type_)
            .map(|owner| owner.edges.clone()))
    };
    for type_ in [condition_type, globals.object_type] {
        store
            .validate_cached_array_capability_with_source_interfaces(
                array_targets,
                type_,
                &[],
                Some(&source_edges),
            )
            .map_err(source_condition_graph_error)?;
    }
    if !walk.pending.is_empty() {
        return Ok(Some(SourceInterfaceConditionPlan::Pending(walk.pending)));
    }
    Ok(Some(SourceInterfaceConditionPlan::Ready(
        SourceInterfaceConditionHeader {
            condition_type,
            receiver,
            global_object_type: globals.object_type,
            _owners: walk.owners,
        },
    )))
}

fn source_interface_condition_request(
    walk: &mut SourceInterfaceConditionWalk,
    request: SourceInterfaceConditionRequest,
) {
    if !walk.pending.contains(&request) {
        walk.pending.push(request);
    }
}

#[allow(clippy::too_many_lines)] // Keep source ownership, local caches and each real base in order.
fn source_interface_condition_owner(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    type_: TypeId,
    array_targets: Option<CanonicalArrayTargets>,
    query: Option<&SourceInterfaceHeritageQueryContext<'_>>,
    walk: &mut SourceInterfaceConditionWalk,
) -> Result<bool, DeclaredTypeError> {
    let record = store
        .type_payload(type_)
        .ok_or(super::TypeNodeUnavailable::InvalidCachedUnionType(type_))?;
    let owner = record
        .symbol()
        .ok_or(super::TypeNodeUnavailable::InvalidCachedUnionType(type_))?;
    let invalid = || source_interface_condition_error(owner, type_);
    let TypeData::Interface(interface) = record.data() else {
        return Err(invalid());
    };
    let symbol = store.symbol(owner).ok_or_else(invalid)?;
    if symbol.flags().contains(SymbolFlags::CLASS) {
        return if super::declared::cached_class_type(store, owner)? == Some(type_) {
            Ok(false)
        } else {
            Err(invalid())
        };
    }
    if !symbol.flags().contains(SymbolFlags::INTERFACE) {
        return Err(invalid());
    }
    if super::declared::preflight_class_or_interface_reference(store, host, owner, symbol.flags())?
        != 0
    {
        return Ok(false);
    }
    if super::declared::cached_interface_type(store, owner)? != Some(type_)
        || !super::structured_members::nongeneric_interface_heritage_type_is_exact(store, type_)
    {
        return Err(invalid());
    }
    if walk.complete.contains(&type_) {
        return Ok(true);
    }
    let declarations = symbol.declarations().ok_or_else(invalid)?;
    let first = *declarations.first().ok_or_else(invalid)?;
    if walk.active.len() >= super::interface_heritage::MAX_INTERFACE_HERITAGE_DEPTH
        || !walk.active.insert(type_)
    {
        return Err(DeclaredTypeUnavailable::UnsupportedInterfaceHeritageResolution(first).into());
    }
    let (names, inherited) = plan_source_member_names(store, host, owner).map_err(|_| invalid())?;
    validate_source_member_name_cache(store, host, owner, &names).map_err(|_| invalid())?;
    if let Some(members) = symbol.members() {
        for (_, member) in store.symbol_table(members).ok_or_else(invalid)?.iter() {
            let member = store.get_merged_symbol(member).ok_or_else(invalid)?;
            validate_cold_source_member_symbol(store, owner, member).map_err(|_| invalid())?;
            let member = store.symbol(member).ok_or_else(invalid)?;
            if member
                .flags()
                .intersects(SymbolFlags::SIGNATURE | SymbolFlags::ACCESSOR)
            {
                return Ok(false);
            }
        }
    }
    if names.iter().any(|member| {
        member.computed.is_some()
            || store
                .source_child_with_kind(member.declaration, SyntaxKind::ComputedPropertyName)
                .is_some()
            || member
                .name
                .as_ref()
                .is_some_and(|name| matches!(name.as_utf8(), Some("bind" | "then")))
    }) {
        return Ok(false);
    }
    let planned_header =
        super::interface_heritage::plan_source_interface_heritage_header(store, host, owner)?;
    match (
        store.source_interface_heritage_header(type_),
        planned_header.as_ref(),
    ) {
        (Some(saved), Some(current)) if saved == current => {}
        (Some(_), _) => return Err(invalid()),
        (None, Some(header)) => source_interface_condition_request(
            walk,
            SourceInterfaceConditionRequest::HeritageHeader {
                receiver: type_,
                header: header.clone(),
            },
        ),
        (None, None) => {}
    }
    let mut edges = Vec::new();
    if let Some(header) = planned_header.as_ref() {
        edges.extend(
            super::interface_heritage::validate_source_interface_heritage_header(
                store,
                type_,
                header,
                array_targets,
            )?,
        );
    }
    let complete = record
        .object_flags()
        .contains(ObjectFlags::MEMBERS_RESOLVED);
    if complete && let Some(header) = planned_header.as_ref() {
        let mut pending = false;
        for request in header.bases().iter().filter_map(|base| base.alias()) {
            if let SourceInterfaceAliasBaseState::Pending { conditional, .. } =
                super::interface_heritage::source_interface_alias_base_state(
                    store,
                    request,
                    array_targets,
                    query,
                )?
            {
                source_interface_condition_request(
                    walk,
                    SourceInterfaceConditionRequest::AliasBase {
                        request: request.clone(),
                        conditional,
                    },
                );
                pending = true;
            }
        }
        if pending {
            walk.deferred_complete = true;
            assert!(walk.active.remove(&type_));
            return Ok(true);
        }
    }
    let merged =
        plan_merged_global_interface_with_query_context(store, host, owner, array_targets, query)
            .map_err(|_| invalid())?;
    if complete {
        for key in ["bind", "then"] {
            let value =
                super::structured_members::validated_interface_property_by_key_with_query_context(
                    store,
                    type_,
                    EscapedName::source(key).as_ref(),
                    array_targets,
                    query,
                )
                .ok_or_else(invalid)?;
            if value.is_some() {
                return Ok(false);
            }
        }
        let structured = &interface.reference.object.structured;
        if structured
            .signatures
            .as_ref()
            .is_some_and(|rows| !rows.is_empty())
            || structured.call_signature_count != 0
            || structured
                .index_infos
                .as_ref()
                .is_some_and(|rows| !rows.is_empty())
        {
            return Ok(false);
        }
        if let Some(members) = structured.members {
            for (_, member) in store.symbol_table(members).ok_or_else(invalid)?.iter() {
                let links = store.value_symbol_links(member).ok_or_else(invalid)?;
                edges.push(links.resolved_type.ok_or_else(invalid)?);
                edges.extend(links.write_type);
            }
        }
    } else {
        if !valid_cold_declared_member_cache(interface)
            || interface.resolved_base_constructor_type.is_some()
            || interface.resolved_base_types.is_some()
            || inherited && interface.base_types_resolved
            || store.direct_interface_heritage_provenance(type_).is_some()
        {
            return Err(invalid());
        }
        edges.extend(
            cold_source_interface_local_member_edges(store, host, owner).map_err(|_| invalid())?,
        );
    }
    edges.extend(interface.this_type);
    edges.extend(interface.reference.object.target);
    edges.extend(
        interface
            .reference
            .resolved_type_arguments
            .iter()
            .flatten()
            .copied(),
    );
    let mut bases = Vec::new();
    if let Some(header) = planned_header.as_ref() {
        for base in header.bases() {
            if let Some(request) = base.alias() {
                match super::interface_heritage::source_interface_alias_base_state(
                    store,
                    request,
                    array_targets,
                    query,
                )? {
                    SourceInterfaceAliasBaseState::Pending {
                        edges: present,
                        conditional,
                    } => {
                        edges.extend(present);
                        source_interface_condition_request(
                            walk,
                            SourceInterfaceConditionRequest::AliasBase {
                                request: request.clone(),
                                conditional,
                            },
                        );
                    }
                    SourceInterfaceAliasBaseState::Ready {
                        type_: base_type,
                        edges: present,
                    } => {
                        if bases.iter().any(|&(symbol, previous)| {
                            previous == base_type && symbol != base.symbol()
                        }) {
                            return Err(
                                DeclaredTypeUnavailable::UnsupportedInterfaceHeritageResolution(
                                    base.node(),
                                )
                                .into(),
                            );
                        }
                        if !source_interface_condition_alias(store, base_type, array_targets)? {
                            return Ok(false);
                        }
                        edges.extend(present);
                        bases.push((base.symbol(), base_type));
                    }
                }
            } else {
                match source_interface_condition_base(
                    store,
                    host,
                    base.symbol(),
                    array_targets,
                    query,
                    walk,
                )? {
                    SourceInterfaceConditionBase::Pending => {}
                    SourceInterfaceConditionBase::Ineligible => return Ok(false),
                    SourceInterfaceConditionBase::Ready(base_type) => {
                        edges.push(base_type);
                        bases.push((base.symbol(), base_type));
                    }
                }
            }
        }
    } else {
        for &declaration in declarations {
            let Some(NodeData::InterfaceDeclaration(interface)) =
                host.node(declaration).map(|node| &node.data)
            else {
                continue;
            };
            let Some(clauses) = interface.heritage_clauses.as_ref() else {
                continue;
            };
            let heritage =
                match plan_direct_interface_heritage(store, host, declaration, owner, clauses) {
                    Ok(heritage) => heritage,
                    Err(DirectInterfaceHeritageError::Unsupported { .. }) => return Ok(false),
                    Err(DirectInterfaceHeritageError::Invalid) => return Err(invalid()),
                };
            for base in heritage.bases {
                if base.kind != DirectInterfaceBaseKind::Interface
                    || !base.type_arguments.is_empty()
                    || !base.defaults.is_empty()
                {
                    return Ok(false);
                }
                match source_interface_condition_base(
                    store,
                    host,
                    base.symbol,
                    array_targets,
                    query,
                    walk,
                )? {
                    SourceInterfaceConditionBase::Pending => {}
                    SourceInterfaceConditionBase::Ineligible => return Ok(false),
                    SourceInterfaceConditionBase::Ready(base_type) => {
                        edges.push(base_type);
                        bases.push((base.symbol, base_type));
                    }
                }
            }
        }
    }
    if !inherited && !bases.is_empty() || merged.as_ref().is_some_and(|plan| plan.symbol != owner) {
        return Err(invalid());
    }
    walk.owners.push(SourceInterfaceConditionOwner {
        type_,
        symbol: owner,
        declarations: declarations.to_vec(),
        members: symbol.members(),
        names: names
            .into_iter()
            .map(|member| {
                Ok((
                    member.declaration,
                    member.symbol,
                    member.name.ok_or_else(invalid)?,
                ))
            })
            .collect::<Result<_, DeclaredTypeError>>()?,
        bases,
        edges,
    });
    assert!(walk.active.remove(&type_));
    walk.complete.insert(type_);
    Ok(true)
}

fn source_interface_condition_base(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    symbol: SemanticSymbolId,
    array_targets: Option<CanonicalArrayTargets>,
    query: Option<&SourceInterfaceHeritageQueryContext<'_>>,
    walk: &mut SourceInterfaceConditionWalk,
) -> Result<SourceInterfaceConditionBase, DeclaredTypeError> {
    let Some(type_) = super::declared::cached_interface_type(store, symbol)? else {
        source_interface_condition_request(
            walk,
            SourceInterfaceConditionRequest::InterfaceIdentity { symbol },
        );
        return Ok(SourceInterfaceConditionBase::Pending);
    };
    Ok(
        if source_interface_condition_owner(store, host, type_, array_targets, query, walk)? {
            SourceInterfaceConditionBase::Ready(type_)
        } else {
            SourceInterfaceConditionBase::Ineligible
        },
    )
}

fn source_interface_condition_alias(
    store: &CanonicalTypeMapperStore,
    type_: TypeId,
    array_targets: Option<CanonicalArrayTargets>,
) -> Result<bool, DeclaredTypeError> {
    let invalid =
        || DeclaredTypeError::from(super::TypeNodeUnavailable::InvalidCachedUnionType(type_));
    if !matches!(
        validate_resolved_declared_property_object(store, type_),
        DeclaredPropertyObjectValidation::Valid(DeclaredPropertyObjectProof::TypeLiteral)
    ) {
        return Err(invalid());
    }
    let structured = store
        .type_payload(type_)
        .and_then(|record| record.data().structured())
        .ok_or_else(invalid)?;
    if structured
        .signatures
        .as_ref()
        .is_some_and(|rows| !rows.is_empty())
        || structured.call_signature_count != 0
        || structured
            .index_infos
            .as_ref()
            .is_some_and(|rows| !rows.is_empty())
    {
        return Ok(false);
    }
    if let Some(members) = structured.members {
        let members = store.symbol_table(members).ok_or_else(invalid)?;
        if members.get_source("bind").is_some() || members.get_source("then").is_some() {
            return Ok(false);
        }
    }
    match array_targets {
        Some(targets) => store.validate_cached_array_capability_with_array_targets(targets, type_),
        None => store.validate_cached_array_capability(type_),
    }
    .map_err(|_| invalid())?;
    Ok(true)
}

/// Checks member ownership without planning unread annotations or signatures.
pub(super) fn preflight_source_interface_member_names(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    owner: SemanticSymbolId,
) -> Result<(), PropertyObjectError> {
    let invalid = || PropertyObjectError::InvalidInterfaceSymbol(owner);
    let (names, heritage) =
        plan_source_member_names(store, host, owner).map_err(|error| match error {
            SourceCheckError::Unsupported(UnsupportedSourceSyntax::Element(node)) => {
                PropertyObjectError::UnsupportedMember {
                    node,
                    kind: store.source_node_kind(node).unwrap_or(SyntaxKind::Unknown),
                }
            }
            _ => invalid(),
        })?;
    if heritage {
        return Err(invalid());
    }
    validate_source_member_name_cache(store, host, owner, &names).map_err(|_| invalid())?;
    let record = store.symbol(owner).ok_or_else(invalid)?;
    if let Some(table) = record.members() {
        for (_, member) in store.symbol_table(table).ok_or_else(invalid)?.iter() {
            let member = store.get_merged_symbol(member).ok_or_else(invalid)?;
            validate_cold_source_member_symbol(store, owner, member)?;
        }
    }
    Ok(())
}

/// Retains published member and annotation edges while the interface stays cold.
#[allow(clippy::too_many_lines)] // Member values and partial signatures share one source/cache proof.
pub(super) fn cold_source_interface_member_edges(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    owner: SemanticSymbolId,
    receiver: Option<TypeId>,
) -> Result<Vec<TypeId>, PropertyObjectError> {
    let invalid = || PropertyObjectError::InvalidInterfaceSymbol(owner);
    preflight_source_interface_member_names(store, host, owner)?;
    if let Some(receiver) = receiver {
        let record = store.type_payload(receiver).ok_or_else(invalid)?;
        let TypeData::Interface(interface) = record.data() else {
            return Err(invalid());
        };
        if record.symbol() != Some(owner)
            || !valid_cold_declared_member_cache(interface)
            || interface.resolved_base_types.is_some()
            || interface.resolved_base_constructor_type.is_some()
        {
            return Err(invalid());
        }
    }
    cold_source_interface_local_member_edges(store, host, owner)
}

/// Checks only local caches after the caller proves the current source header.
#[allow(clippy::too_many_lines)] // Keep the existing member and annotation checks in one reader.
fn cold_source_interface_local_member_edges(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    owner: SemanticSymbolId,
) -> Result<Vec<TypeId>, PropertyObjectError> {
    let invalid = || PropertyObjectError::InvalidInterfaceSymbol(owner);
    let (names, _) = plan_source_member_names(store, host, owner).map_err(|_| invalid())?;
    let mut computed_expressions = HashMap::new();
    let mut edges = Vec::new();
    for key in names.iter().filter_map(|member| member.computed) {
        preflight_planned_computed_key_value(store, host, &key).map_err(|_| invalid())?;
        if let Some((type_, _)) =
            resolved_computed_member_key(store, &key).map_err(|_| invalid())?
        {
            computed_expressions.insert(key.expression, type_);
            edges.push(type_);
        }
        if let Some(NodeData::PropertyAccessExpression(property)) =
            host.node(key.expression).map(|record| &record.data)
        {
            // The computed-key planner authenticated this receiver's source and value identity.
            let receiver = NodeRef::new(
                key.expression.arena,
                key.expression.file,
                property.expression,
            );
            if let Some(type_) = store
                .type_node_links(receiver)
                .and_then(|links| links.resolved_type)
            {
                if computed_member_property_symbol(store, host, key.expression)
                    .map_err(|_| invalid())?
                    != key.key_symbol
                {
                    return Err(invalid());
                }
                computed_expressions.insert(receiver, type_);
            }
        }
    }
    let mut members = Vec::new();
    for declaration in store
        .symbol(owner)
        .and_then(ts_binder::semantic::Symbol::declarations)
        .ok_or_else(invalid)?
    {
        let record = preflight_node(store, host, *declaration).map_err(|_| invalid())?;
        if let NodeData::InterfaceDeclaration(interface) = &record.data {
            for member in &interface.members.nodes {
                let node = NodeRef::new(declaration.arena, declaration.file, *member);
                let symbol = bound_symbol(store, host, node).ok_or_else(invalid)?;
                if !members.contains(&symbol) {
                    members.push(symbol);
                }
            }
        }
    }
    for member in members {
        validate_cold_source_member_symbol(store, owner, member)?;
        let record = store.symbol(member).ok_or_else(invalid)?;
        let declarations = record.declarations().ok_or_else(invalid)?;
        let value = store.value_symbol_links(member);
        let mut published = false;
        if record.flags().contains(SymbolFlags::METHOD)
            && (value.is_some_and(|links| links.resolved_type.is_some())
                || store
                    .late_bound_links(member)
                    .and_then(|links| links.late_symbol)
                    .is_some())
        {
            let plan = plan_selected_interface_method(store, host, member)?;
            edges.push(interface_method_value_state(store, &plan)?.ok_or_else(invalid)?);
            published = true;
        } else if value.is_some_and(|links| links != &ValueSymbolLinks::default()) {
            // A property query can publish before its interface identity exists.
            let plan = plan_declared_value(store, host, member).map_err(|_| invalid())?;
            let type_ = plan.cached_type.ok_or_else(invalid)?;
            if store.declared_value_provenance(member).is_none_or(|proof| {
                proof.annotation != plan.annotation
                    || proof.type_ != type_
                    || proof.readonly != plan.readonly
                    || !proof.is_current(store, member)
            }) {
                return Err(invalid());
            }
            edges.push(type_);
        } else if store.declared_value_provenance(member).is_some() {
            return Err(invalid());
        }
        for &declaration in declarations {
            let signature_published = store
                .signature_links(declaration)
                .is_some_and(|links| links != &SignatureLinks::default());
            let member_published = if !published && signature_published {
                // Partial constructs already have a full source plan from their publisher.
                // Reuse that proof only when a signature has actually been published.
                if store.source_node_kind(declaration) != Some(SyntaxKind::ConstructSignature) {
                    return Err(invalid());
                }
                let plan = plan_interface(store, host, owner)?;
                let planned = plan
                    .call_signatures
                    .iter()
                    .find(|signature| signature.declaration == declaration)
                    .ok_or_else(invalid)?;
                let signature =
                    authenticated_partial_declared_construct_signature(store, &plan, planned)
                        .or_else(|| {
                            authenticated_lazy_global_constructor_signature(store, &plan, planned)
                        })
                        .ok_or_else(invalid)?;
                let signature = store.signature(signature).ok_or_else(invalid)?;
                edges.push(signature.resolved_return_type().ok_or_else(invalid)?);
                for parameter in signature.parameters() {
                    edges.push(
                        store
                            .value_symbol_links(*parameter)
                            .and_then(|links| links.resolved_type)
                            .ok_or_else(invalid)?,
                    );
                }
                true
            } else {
                published
            };
            collect_cold_source_member_annotation_edges(
                store,
                host,
                owner,
                declaration,
                member_published,
                &computed_expressions,
                &mut edges,
            )?;
        }
    }
    Ok(edges)
}

pub(super) fn validate_cold_source_member_symbol(
    store: &CanonicalTypeMapperStore,
    owner: SemanticSymbolId,
    member: SemanticSymbolId,
) -> Result<(), PropertyObjectError> {
    let invalid = || PropertyObjectError::InvalidInterfaceSymbol(owner);
    let record = store.symbol(member).ok_or_else(invalid)?;
    let declarations = record
        .declarations()
        .filter(|declarations| !declarations.is_empty())
        .ok_or_else(invalid)?;
    let mut flags = SymbolFlags::NONE;
    let mut readonly = false;
    let mut signature_name = None;
    for &declaration in declarations {
        flags |= match store.source_node_kind(declaration) {
            Some(SyntaxKind::MethodSignature) => SymbolFlags::METHOD,
            Some(SyntaxKind::PropertyDeclaration | SyntaxKind::PropertySignature) => {
                readonly |= store
                    .source_child_with_kind(declaration, SyntaxKind::ReadonlyKeyword)
                    .is_some();
                SymbolFlags::PROPERTY
            }
            Some(SyntaxKind::GetAccessor) => SymbolFlags::GET_ACCESSOR,
            Some(SyntaxKind::SetAccessor) => SymbolFlags::SET_ACCESSOR,
            Some(
                kind @ (SyntaxKind::CallSignature
                | SyntaxKind::ConstructSignature
                | SyntaxKind::IndexSignature),
            ) => {
                let name = match kind {
                    SyntaxKind::CallSignature => InternalSymbolName::Call,
                    SyntaxKind::ConstructSignature => InternalSymbolName::New,
                    _ => InternalSymbolName::Index,
                };
                if signature_name.is_some_and(|previous| previous != name) {
                    return Err(invalid());
                }
                signature_name = Some(name);
                SymbolFlags::SIGNATURE
            }
            _ => return Err(invalid()),
        };
        if store
            .source_child_with_kind(declaration, SyntaxKind::QuestionToken)
            .is_some()
        {
            flags |= SymbolFlags::OPTIONAL;
        }
    }
    if record.flags().without(SymbolFlags::TRANSIENT) != flags
        || record.check_flags() != CheckFlags::NONE
            && (!readonly || record.check_flags() != CheckFlags::READONLY)
        || record.value_declaration()
            != if signature_name.is_some() {
                None
            } else {
                declarations.first().copied()
            }
        || signature_name.is_some_and(|name| record.name() != name.as_ref())
        || record.members().is_some()
        || record.exports().is_some()
        || record.export_symbol().is_some()
        || store.get_parent_of_symbol(member) != Some(owner)
        || store.get_merged_symbol(member) != Some(member)
        || !store.source_merged_symbol_declarations_match(member)
    {
        return Err(invalid());
    }
    Ok(())
}

/// Unread call, construct, and index members can still have queried annotations.
pub(super) fn collect_cold_source_member_annotation_edges(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    owner: SemanticSymbolId,
    declaration: NodeRef,
    published: bool,
    computed_expressions: &HashMap<NodeRef, TypeId>,
    edges: &mut Vec<TypeId>,
) -> Result<(), PropertyObjectError> {
    let invalid = || PropertyObjectError::InvalidInterfaceSymbol(owner);
    let mut pending = vec![declaration];
    let mut visited = HashSet::new();
    while let Some(node) = pending.pop() {
        if !visited.insert(node) {
            return Err(invalid());
        }
        let record = preflight_node(store, host, node).map_err(|_| invalid())?;
        if let Some(links) = store.type_node_links(node) {
            if let Some(type_) = links.resolved_type {
                let computed = computed_expressions.get(&node) == Some(&type_)
                    && links
                        == &TypeNodeLinks {
                            resolved_type: Some(type_),
                            ..TypeNodeLinks::default()
                        };
                if !computed
                    && (!record.kind.is_keyword_type()
                        && !(SyntaxKind::FIRST_TYPE_NODE as u16
                            ..=SyntaxKind::LAST_TYPE_NODE as u16)
                            .contains(&(record.kind as u16))
                        || super::callable_sets::validated_method_annotation_type(store, node)
                            != Some(type_))
                {
                    return Err(invalid());
                }
                edges.push(type_);
                if matches!(
                    record.kind,
                    SyntaxKind::FunctionType | SyntaxKind::ConstructorType
                ) && matches!(
                    super::callable_sets::validate_stored_callable_set(store, type_),
                    super::callable_sets::StoredCallableSetValidation::Valid { .. }
                ) {
                    continue;
                }
            } else if links != &TypeNodeLinks::default() {
                return Err(invalid());
            }
        }
        if store
            .signature_links(node)
            .is_some_and(|links| links != &SignatureLinks::default())
            && !(published && node == declaration)
        {
            return Err(invalid());
        }
        if node != declaration
            && let Some(symbol) = store.source_declaration_symbol(node)
            && (!store.source_merged_symbol_declarations_match(symbol)
                || store
                    .late_bound_links(symbol)
                    .is_some_and(|links| links != &super::links::LateBoundLinks::default())
                || store
                    .value_symbol_links(symbol)
                    .is_some_and(|links| links != &ValueSymbolLinks::default())
                    && !(published
                        && matches!(
                            record.kind,
                            SyntaxKind::Parameter | SyntaxKind::BindingElement
                        )))
        {
            return Err(invalid());
        }
        let children = store.source_direct_children(node).ok_or_else(invalid)?;
        if children
            .iter()
            .any(|child| store.source_node_parent(*child) != Some(SourceNodeParent::Parent(node)))
        {
            return Err(invalid());
        }
        pending.extend(children);
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)] // The preflight uses the same source query context as execution.
fn preflight_source_member_selection(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    global_types: &CanonicalGlobalTypes,
    options: CanonicalCheckerOptions,
    owner: SemanticSymbolId,
    receiver: TypeId,
    name: EscapedNameRef<'_>,
    session: &mut InstantiationSession,
    diagnostics: &mut CanonicalCheckerDiagnostics,
) -> Result<Option<SemanticSymbolId>, SourceCheckError> {
    let (names, has_heritage) = plan_source_member_names(store, host, owner)?;
    validate_source_member_name_cache(store, host, owner, &names)?;
    let mut selected: Option<&SourceMemberName> = None;
    for member in &names {
        if !source_member_name_matches(store, member, name)? {
            continue;
        }
        if selected.is_some_and(|previous| {
            previous.symbol != member.symbol
                && !(previous
                    .computed
                    .zip(member.computed)
                    .is_some_and(|(first, next)| first.key_symbol == next.key_symbol)
                    && [previous.symbol, member.symbol].into_iter().all(|symbol| {
                        store
                            .symbol(symbol)
                            .is_some_and(|symbol| symbol.flags().contains(SymbolFlags::METHOD))
                    }))
        }) {
            return Err(SourceCheckError::Unsupported(
                UnsupportedSourceSyntax::Element(member.declaration),
            ));
        }
        selected = Some(member);
    }
    let Some(selected) = selected else {
        return if has_heritage {
            Err(RelationUnavailable::UnsupportedStructuredType(receiver).into())
        } else {
            Ok(None)
        };
    };
    let symbol = selected.symbol;
    let method = store
        .symbol(symbol)
        .ok_or(RelationUnavailable::Symbol(symbol))?
        .flags()
        .contains(SymbolFlags::METHOD);
    let query = CanonicalTypeQuery::new_with_global_types_and_session(
        store,
        host,
        global_types,
        options,
        session,
        diagnostics,
    )?;
    if method {
        query.preflight_type_of_interface_method(symbol)?;
    } else {
        query.preflight_type_of_declared_value(symbol)?;
    }
    Ok(Some(symbol))
}

fn source_member_name_matches(
    store: &CanonicalTypeMapperStore,
    member: &SourceMemberName,
    requested: EscapedNameRef<'_>,
) -> Result<bool, SourceCheckError> {
    if let Some(name) = &member.name {
        return Ok(name.as_ref() == requested);
    }
    let key = member
        .computed
        .ok_or(RelationUnavailable::Symbol(member.symbol))?;
    let record = store
        .symbol(key.key_symbol)
        .ok_or(RelationUnavailable::Symbol(key.key_symbol))?;
    // A unique-symbol query key already carries an assigned identity. Do not
    // create identities or resolve unrelated key annotations during selection.
    let Some(identity) = store
        .symbol_store()
        .assigned_global_symbol_id(key.key_symbol)
    else {
        return Ok(false);
    };
    let suffix = requested
        .as_bytes()
        .strip_prefix(b"\xFE@")
        .and_then(|name| name.strip_prefix(record.name().as_bytes()))
        .and_then(|name| name.strip_prefix(b"@"));
    Ok(suffix == Some(identity.to_string().as_bytes()))
}

pub(super) fn source_generic_member_error(
    receiver: TypeId,
    error: &GenericInterfaceMemberError,
) -> SourceCheckError {
    match error {
        GenericInterfaceMemberError::UnsupportedTarget(type_)
        | GenericInterfaceMemberError::UnsupportedPropertyType(type_) => {
            RelationUnavailable::UnsupportedStructuredType(*type_).into()
        }
        GenericInterfaceMemberError::UnsupportedMember(symbol) => {
            RelationUnavailable::UnsupportedProperty(*symbol).into()
        }
        GenericInterfaceMemberError::Capacity(type_) => {
            RelationUnavailable::UnionValidationCapacity(*type_).into()
        }
        GenericInterfaceMemberError::Reference(_)
        | GenericInterfaceMemberError::InvalidTarget(_)
        | GenericInterfaceMemberError::InvalidMember(_)
        | GenericInterfaceMemberError::InvalidCachedMembers(_)
        | GenericInterfaceMemberError::InvalidCachedProperty(_) => {
            RelationUnavailable::InvalidStructuredMembers(receiver).into()
        }
    }
}

fn source_computed_key_error(error: ComputedMemberKeyError) -> SourceCheckError {
    match error {
        ComputedMemberKeyError::Unsupported(node) => {
            SourceCheckError::Unsupported(UnsupportedSourceSyntax::Element(node))
        }
        ComputedMemberKeyError::Invalid(node) | ComputedMemberKeyError::Capacity(node) => {
            SourceCheckError::Element(node)
        }
    }
}

fn validate_source_member_name_cache(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    owner: SemanticSymbolId,
    names: &[SourceMemberName],
) -> Result<(), SourceCheckError> {
    let invalid = || RelationUnavailable::Symbol(owner);
    let raw = store.symbol(owner).ok_or_else(invalid)?.members();
    let resolved = store.members_and_exports_links(owner).and_then(|links| {
        links.table(super::links::MembersOrExportsResolutionKind::ResolvedMembers)
    });
    if resolved
        .is_some_and(|resolved| !valid_partial_member_name_table(store, owner, raw, resolved))
    {
        return Err(invalid().into());
    }
    let table = resolved.and_then(|table| store.symbol_table(table));
    if resolved
        .is_some_and(|resolved| !valid_partial_member_name_sources(store, raw, resolved, names))
    {
        return Err(invalid().into());
    }
    for member in names.iter().filter(|member| member.computed.is_some()) {
        let late = store
            .late_bound_links(member.symbol)
            .and_then(|links| links.late_symbol);
        let Some(late) = late else {
            if store
                .symbol_node_links(member.declaration)
                .is_some_and(|links| links != &SymbolNodeLinks::default())
                || store
                    .value_symbol_links(member.symbol)
                    .is_some_and(|links| links != &ValueSymbolLinks::default())
            {
                return Err(invalid().into());
            }
            continue;
        };
        let source = store.symbol(member.symbol).ok_or_else(invalid)?;
        let declarations = store
            .symbol(late)
            .and_then(ts_binder::semantic::Symbol::declarations)
            .ok_or_else(invalid)?;
        let links = store.value_symbol_links(late).ok_or_else(invalid)?;
        if !super::structured_members::valid_late_bound_unique_symbol_member(
            store,
            owner,
            late,
            declarations,
            links,
            table,
        ) {
            return Err(invalid().into());
        }
        let value = links.resolved_type.ok_or_else(invalid)?;
        if source.flags().contains(SymbolFlags::METHOD) {
            let plan = plan_selected_interface_method(store, host, member.symbol)
                .map_err(|_| invalid())?;
            if interface_method_value_state(store, &plan).map_err(|_| invalid())? != Some(value) {
                return Err(invalid().into());
            }
        } else if store
            .source_direct_type_annotation(member.declaration)
            .is_none_or(|annotation| {
                !store.source_direct_type_annotation_is_exact(annotation, value)
            })
        {
            return Err(invalid().into());
        }
    }
    Ok(())
}

/// Symbol parents can change, so cached entries need their original source member.
fn valid_partial_member_name_sources(
    store: &CanonicalTypeMapperStore,
    raw: Option<SymbolTableId>,
    cached: SymbolTableId,
    names: &[SourceMemberName],
) -> bool {
    let Some(table) = store.symbol_table(cached) else {
        return false;
    };
    let binder = raw.and_then(|raw| store.symbol_table(raw));
    table.iter().all(|(name, late)| {
        if binder.and_then(|binder| binder.get(name)) == Some(late) {
            return true;
        }
        let Some(record) = store.symbol(late) else {
            return false;
        };
        let Some(declarations) = record.declarations() else {
            return false;
        };
        if record.flags().contains(SymbolFlags::METHOD) {
            let Some(sources) = store.late_bound_method_sources(late) else {
                return false;
            };
            let members = names
                .iter()
                .filter(|member| {
                    member.computed.is_some()
                        && member
                            .name
                            .as_ref()
                            .is_some_and(|expected| expected.as_ref() == name)
                })
                .collect::<Vec<_>>();
            return sources.len() == declarations.len()
                && members.len() == declarations.len()
                && members.into_iter().zip(declarations).zip(sources).all(
                    |((member, declaration), source)| {
                        member.declaration == *declaration
                            && member.symbol == source
                            && store.source_declaration_symbol(*declaration) == Some(source)
                            && store
                                .late_bound_links(source)
                                .and_then(|links| links.late_symbol)
                                == Some(late)
                    },
                );
        }
        names.iter().any(|member| {
            member.computed.is_some()
                && member
                    .name
                    .as_ref()
                    .is_some_and(|expected| expected.as_ref() == name)
                && declarations.contains(&member.declaration)
                && store
                    .symbol(member.symbol)
                    .and_then(|source| source.declarations())
                    == Some(declarations)
                && store
                    .late_bound_links(member.symbol)
                    .and_then(|links| links.late_symbol)
                    == Some(late)
        })
    })
}

/// Checks the shared raw entries and every published computed-name entry.
fn valid_partial_member_name_table(
    store: &CanonicalTypeMapperStore,
    owner: SemanticSymbolId,
    raw: Option<SymbolTableId>,
    cached: SymbolTableId,
) -> bool {
    let Some(members) = store.symbol_table(cached) else {
        return false;
    };
    let binder = raw.and_then(|table| store.symbol_table(table));
    Some(cached) != raw
        && raw.is_some() == binder.is_some()
        && binder.is_none_or(|binder| {
            binder
                .iter()
                .all(|(name, symbol)| members.get(name) == Some(symbol))
        })
        && members.iter().all(|(name, symbol)| {
            if binder.and_then(|binder| binder.get(name)) == Some(symbol) {
                return true;
            }
            store.symbol(symbol).is_some_and(|record| {
                record.name() == name
                    && store.value_symbol_links(symbol).is_some_and(|value| {
                        record.declarations().is_some_and(|declarations| {
                            super::structured_members::valid_late_bound_unique_symbol_member(
                                store,
                                owner,
                                symbol,
                                declarations,
                                value,
                                Some(members),
                            )
                        })
                    })
            })
        })
}

fn plan_source_member_names(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    owner: SemanticSymbolId,
) -> Result<(Vec<SourceMemberName>, bool), SourceCheckError> {
    let invalid = || SourceCheckError::RelationUnavailable(RelationUnavailable::Symbol(owner));
    let symbol = store.symbol(owner).ok_or_else(invalid)?;
    let interface_owner = symbol.flags().contains(SymbolFlags::INTERFACE);
    let mixed_owner = if interface_owner
        && !source_interface_uses_legacy_single_script_value_owner(store, owner)
    {
        store
            .source_global_interface_value_owner(owner)
            .map_err(|_| invalid())?
    } else {
        None
    };
    if interface_owner {
        super::declared::preflight_class_or_interface_reference(
            store,
            host,
            owner,
            symbol.flags(),
        )?;
    }
    let allowed = if interface_owner {
        SymbolFlags::INTERFACE | SymbolFlags::TRANSIENT | SymbolFlags::FUNCTION_SCOPED_VARIABLE
    } else {
        SymbolFlags::TYPE_LITERAL
    };
    if symbol.flags().without(allowed) != SymbolFlags::NONE
        || symbol.check_flags() != CheckFlags::NONE
        || symbol.exports().is_some()
        || symbol.export_symbol().is_some()
        || store.get_merged_symbol(owner) != Some(owner)
    {
        return Err(invalid());
    }
    let declarations = symbol
        .declarations()
        .filter(|declarations| !declarations.is_empty())
        .ok_or_else(invalid)?;
    let table = symbol
        .members()
        .map(|members| store.symbol_table(members).ok_or_else(invalid))
        .transpose()?;
    let mut names = Vec::new();
    let mut seen_nodes = HashSet::new();
    let mut seen_symbols = HashMap::<SemanticSymbolId, Vec<NodeRef>>::new();
    let mut has_heritage = false;
    let mut saw_owner = false;
    for &declaration in declarations {
        let record = preflight_node(store, host, declaration)?;
        if !host.symbol_matches(store, declaration, owner)
            || record.flags.0 != 0
            || !seen_nodes.insert(declaration)
        {
            return Err(invalid());
        }
        let (members, parameters) = match &record.data {
            NodeData::InterfaceDeclaration(interface) if interface_owner => {
                let name = NodeRef::new(declaration.arena, declaration.file, interface.name);
                if store.source_identifier_text(name) != symbol.name().as_utf8()
                    || interface.flow_node.is_some()
                    || interface.local_symbol.is_some()
                    || interface.symbol.is_some()
                {
                    return Err(invalid());
                }
                let parent = declared_type_declaration_parent(
                    store,
                    host,
                    declaration,
                    owner,
                    name,
                    interface.modifiers.as_ref(),
                )
                .map_err(|()| invalid())?;
                if store.get_parent_of_symbol(owner) != parent {
                    return Err(invalid());
                }
                has_heritage |= interface.heritage_clauses.is_some();
                (&interface.members, interface.type_parameters.as_ref())
            }
            NodeData::TypeLiteralNode(literal) if !interface_owner => (&literal.members, None),
            NodeData::VariableDeclaration(_)
                if interface_owner
                    && symbol
                        .flags()
                        .contains(SymbolFlags::FUNCTION_SCOPED_VARIABLE)
                    && (symbol.value_declaration() == Some(declaration)
                        || mixed_owner
                            .as_ref()
                            .is_some_and(|proof| proof.variables().contains(&declaration))) =>
            {
                continue;
            }
            _ => return Err(invalid()),
        };
        saw_owner = true;
        if members.has_trailing_comma {
            return Err(invalid());
        }
        for parameter in parameters
            .into_iter()
            .flat_map(|parameters| &parameters.nodes)
        {
            let node = NodeRef::new(declaration.arena, declaration.file, *parameter);
            let symbol = bound_symbol(store, host, node).ok_or_else(invalid)?;
            let parameter = store.symbol(symbol).ok_or_else(invalid)?;
            if table
                .and_then(|members| members.get(parameter.name()))
                .and_then(|symbol| store.get_merged_symbol(symbol))
                != Some(symbol)
            {
                return Err(invalid());
            }
            seen_symbols.entry(symbol).or_default().push(node);
        }
        for &node in &members.nodes {
            let member = NodeRef::new(declaration.arena, declaration.file, node);
            let record = preflight_node(store, host, member)?;
            if record.parent != Some(declaration.node)
                || record.flags.0 != 0
                || !seen_nodes.insert(member)
            {
                return Err(invalid());
            }
            let member_symbol = bound_symbol(store, host, member).ok_or_else(invalid)?;
            let bound = store.symbol(member_symbol).ok_or_else(invalid)?;
            if store.get_parent_of_symbol(member_symbol) != Some(owner)
                || bound
                    .declarations()
                    .is_none_or(|nodes| !nodes.contains(&member))
            {
                return Err(invalid());
            }
            seen_symbols.entry(member_symbol).or_default().push(member);
            let name_node = match &record.data {
                NodeData::MethodSignatureDeclaration(method) => method.name,
                NodeData::PropertyDeclaration(property) => property.name,
                NodeData::PropertySignatureDeclaration(property) => property.name,
                NodeData::GetAccessorDeclaration(accessor) => accessor.name,
                NodeData::SetAccessorDeclaration(accessor) => accessor.name,
                _ if matches!(
                    record.kind,
                    SyntaxKind::CallSignature
                        | SyntaxKind::ConstructSignature
                        | SyntaxKind::IndexSignature
                ) =>
                {
                    continue;
                }
                _ => {
                    return Err(SourceCheckError::Unsupported(
                        UnsupportedSourceSyntax::Element(member),
                    ));
                }
            };
            let name_node = NodeRef::new(member.arena, member.file, name_node);
            let name_record = preflight_node(store, host, name_node)?;
            if name_record.parent != Some(member.node) {
                return Err(invalid());
            }
            let (name, computed) = match &name_record.data {
                NodeData::ComputedPropertyName(computed) => {
                    let expression =
                        NodeRef::new(name_node.arena, name_node.file, computed.expression);
                    let static_name = if matches!(
                        store.source_node_kind(expression),
                        Some(
                            SyntaxKind::StringLiteral
                                | SyntaxKind::NumericLiteral
                                | SyntaxKind::NoSubstitutionTemplateLiteral
                        )
                    ) {
                        source_static_member_name(store, host, expression)?
                    } else {
                        None
                    };
                    if let Some(name) = static_name {
                        (Some(name), None)
                    } else {
                        let key = plan_computed_member_key(store, host, name_node)
                            .map_err(source_computed_key_error)?;
                        let cached = resolved_computed_member_key(store, &key)
                            .map_err(source_computed_key_error)?
                            .map(|(_, name)| name);
                        (cached, Some(key))
                    }
                }
                _ => (source_static_member_name(store, host, name_node)?, None),
            };
            if computed.is_none() {
                let name = name.as_ref().ok_or_else(invalid)?;
                if bound.name() != name.as_ref()
                    || table
                        .and_then(|members| members.get(name.as_ref()))
                        .and_then(|symbol| store.get_merged_symbol(symbol))
                        != Some(member_symbol)
                {
                    return Err(invalid());
                }
            } else if bound.name() != InternalSymbolName::Computed.as_ref() {
                return Err(invalid());
            }
            names.push(SourceMemberName {
                declaration: member,
                symbol: member_symbol,
                name,
                computed,
            });
        }
    }
    if !saw_owner
        || table.is_some_and(|table| {
            table.iter().any(|(name, symbol)| {
                store
                    .get_merged_symbol(symbol)
                    .and_then(|symbol| store.symbol(symbol).map(|record| (symbol, record)))
                    .is_none_or(|(symbol, record)| {
                        record.name() != name || !seen_symbols.contains_key(&symbol)
                    })
            })
        })
        || seen_symbols.iter().any(|(symbol, nodes)| {
            store
                .symbol(*symbol)
                .and_then(ts_binder::semantic::Symbol::declarations)
                .is_none_or(|declarations| {
                    declarations.len() != nodes.len()
                        || declarations
                            .iter()
                            .any(|declaration| !nodes.contains(declaration))
                })
        })
    {
        return Err(invalid());
    }
    Ok((names, has_heritage))
}

fn source_static_member_name(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    node: NodeRef,
) -> Result<Option<EscapedName>, SourceCheckError> {
    let record = preflight_node(store, host, node)?;
    let text = match &record.data {
        NodeData::Identifier(identifier) => Some(identifier.text.as_str()),
        NodeData::StringLiteral(literal) => Some(literal.text.as_str()),
        NodeData::NumericLiteral(literal) => Some(literal.text.as_str()),
        NodeData::NoSubstitutionTemplateLiteral(literal) => Some(literal.text.as_str()),
        _ => None,
    };
    Ok(text.map(EscapedName::source))
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum KnownSymbolKeyError {
    MissingBootstrap,
    MissingGlobalTypes,
    InvalidSymbol(SemanticSymbolId),
    InvalidType(TypeId),
    NeedsValueType {
        symbol: SemanticSymbolId,
        annotation: Option<NodeRef>,
    },
    Relation(RelationUnavailable),
}

/// Gets the actual global `Symbol.iterator` key before the pinned fallback.
/// An unresolved value is a query dependency, not a missing global symbol.
#[cfg_attr(not(test), allow(dead_code))]
pub(super) fn iterator_key(
    store: &mut CanonicalTypeMapperStore,
) -> Result<EscapedName, KnownSymbolKeyError> {
    known_symbol_key(store, None, "iterator")
}

#[cfg_attr(not(test), allow(dead_code))]
pub(super) fn iterator_key_with_global_types(
    store: &mut CanonicalTypeMapperStore,
    globals: &CanonicalGlobalTypes,
) -> Result<EscapedName, KnownSymbolKeyError> {
    known_symbol_key(store, Some(globals), "iterator")
}

fn known_symbol_key(
    store: &mut CanonicalTypeMapperStore,
    global_types: Option<&CanonicalGlobalTypes>,
    name: &str,
) -> Result<EscapedName, KnownSymbolKeyError> {
    let bootstrap = store
        .intrinsic_bootstrap()
        .ok_or(KnownSymbolKeyError::MissingBootstrap)?;
    let globals = store
        .symbol_table(bootstrap.globals)
        .ok_or(KnownSymbolKeyError::MissingBootstrap)?;
    let fallback = || ts_binder::semantic::SymbolStore::known_symbol_name(name);
    let Some(raw) = globals.get_source("Symbol") else {
        return Ok(fallback());
    };
    let symbol = store
        .get_merged_symbol(raw)
        .ok_or(KnownSymbolKeyError::InvalidSymbol(raw))?;
    let record = store
        .symbol(symbol)
        .ok_or(KnownSymbolKeyError::InvalidSymbol(symbol))?;
    if record.name().as_utf8() != Some("Symbol") || record.check_flags() != CheckFlags::NONE {
        return Err(KnownSymbolKeyError::InvalidSymbol(symbol));
    }
    if !record.flags().intersects(SymbolFlags::VALUE) {
        if record.flags().contains(SymbolFlags::ALIAS) {
            return Err(KnownSymbolKeyError::NeedsValueType {
                symbol,
                annotation: None,
            });
        }
        return Ok(fallback());
    }
    let declaration = record
        .value_declaration()
        .ok_or(KnownSymbolKeyError::InvalidSymbol(symbol))?;
    let symbol_flags = record.flags();
    if record
        .declarations()
        .is_none_or(|declarations| !declarations.contains(&declaration))
        || store.source_node_kind(declaration).is_none()
    {
        return Err(KnownSymbolKeyError::InvalidSymbol(symbol));
    }
    let annotation = store.source_direct_type_annotation(declaration);
    let annotation_type =
        annotation.and_then(|annotation| cached_planned_type_identity(store, annotation));
    if annotation
        .and_then(|annotation| store.type_node_links(annotation))
        .and_then(|links| links.resolved_type)
        .zip(annotation_type)
        .is_some_and(|(cached, expected)| cached != expected)
    {
        return Err(KnownSymbolKeyError::InvalidSymbol(symbol));
    }
    let links = store
        .value_symbol_links(symbol)
        .cloned()
        .unwrap_or_default();
    if links
        != (ValueSymbolLinks {
            resolved_type: links.resolved_type,
            ..ValueSymbolLinks::default()
        })
        || links
            .resolved_type
            .zip(annotation_type)
            .is_some_and(|(value, annotation)| value != annotation)
    {
        return Err(KnownSymbolKeyError::InvalidSymbol(symbol));
    }
    let value_type = links
        .resolved_type
        .or(annotation_type)
        .ok_or(KnownSymbolKeyError::NeedsValueType { symbol, annotation })?;
    if store
        .declared_value_provenance(symbol)
        .is_some_and(|provenance| !provenance.is_current(store, symbol))
    {
        return Err(KnownSymbolKeyError::InvalidSymbol(symbol));
    }
    let value = store
        .type_payload(value_type)
        .ok_or(KnownSymbolKeyError::InvalidType(value_type))?;
    if symbol_flags.contains(SymbolFlags::CLASS)
        && super::classes::authenticated_class_constructor_value(store, symbol)
            .is_none_or(|(type_, _)| type_ != value_type)
        || symbol_flags.intersects(SymbolFlags::FUNCTION | SymbolFlags::VALUE_MODULE)
            && value.symbol() != Some(symbol)
    {
        return Err(KnownSymbolKeyError::InvalidSymbol(symbol));
    }
    if let Some(annotation) = annotation
        .filter(|annotation| store.source_node_kind(*annotation) == Some(SyntaxKind::TypeReference))
    {
        let mut target = store
            .symbol_node_links(annotation)
            .and_then(|links| links.resolved_symbol)
            .and_then(|target| store.get_merged_symbol(target))
            .ok_or(KnownSymbolKeyError::InvalidSymbol(symbol))?;
        let mut aliases = HashSet::new();
        while store
            .symbol(target)
            .is_some_and(|record| record.flags().contains(SymbolFlags::ALIAS))
        {
            if !aliases.insert(target) {
                return Err(KnownSymbolKeyError::InvalidSymbol(target));
            }
            target = store
                .alias_symbol_links(target)
                .and_then(|links| links.alias_target.symbol())
                .and_then(|target| store.get_merged_symbol(target))
                .ok_or(KnownSymbolKeyError::InvalidSymbol(target))?;
        }
        let target_record = store
            .symbol(target)
            .ok_or(KnownSymbolKeyError::InvalidSymbol(target))?;
        let identity_matches = if target_record.flags().contains(SymbolFlags::TYPE_ALIAS) {
            store
                .type_alias_links(target)
                .is_some_and(|links| links.declared_type == Some(value_type))
                || value
                    .alias()
                    .and_then(|alias| store.type_alias(alias))
                    .is_some_and(|alias| alias.symbol() == Some(target))
        } else {
            value.symbol() == Some(target)
        };
        if !identity_matches {
            return Err(KnownSymbolKeyError::InvalidSymbol(symbol));
        }
    }
    if value.flags().intersects(TypeFlags::ANY) {
        return Ok(fallback());
    }
    let signatures = value
        .data()
        .structured()
        .map(|structured| {
            (
                structured.call_signature_count,
                structured.signatures.as_deref().map_or(0, <[_]>::len),
            )
        })
        .unwrap_or_default();
    let mut session = InstantiationSession::new(InstantiationLimits::default());
    let mut property = resolve_object_property_by_key(
        store,
        global_types,
        value_type,
        EscapedNameRef::source(name),
        &mut session,
    )
    .map_err(|error| match error {
        RelationUnavailable::UnresolvedPropertyType(symbol) => {
            KnownSymbolKeyError::NeedsValueType {
                symbol,
                annotation: store
                    .symbol(symbol)
                    .and_then(ts_binder::semantic::Symbol::value_declaration)
                    .and_then(|declaration| store.source_direct_type_annotation(declaration)),
            }
        }
        error => KnownSymbolKeyError::Relation(error),
    })?;
    if property.is_none() {
        if let Some(global_types) = global_types {
            let function = if signatures.0 != 0 {
                Some(global_types.callable_function_type)
            } else if signatures.1 != 0 {
                Some(global_types.newable_function_type)
            } else {
                None
            };
            for augment in function
                .into_iter()
                .chain(std::iter::once(global_types.object_type))
            {
                property = resolve_object_property_by_key(
                    store,
                    Some(global_types),
                    augment,
                    EscapedNameRef::source(name),
                    &mut session,
                )
                .map_err(KnownSymbolKeyError::Relation)?;
                if property.is_some() {
                    break;
                }
            }
        } else {
            let globals = store
                .intrinsic_bootstrap()
                .and_then(|bootstrap| store.symbol_table(bootstrap.globals))
                .ok_or(KnownSymbolKeyError::MissingBootstrap)?;
            if globals.get_source("Object").is_some()
                || signatures.1 != 0
                    && ["Function", "CallableFunction", "NewableFunction"]
                        .into_iter()
                        .any(|name| globals.get_source(name).is_some())
            {
                return Err(KnownSymbolKeyError::MissingGlobalTypes);
            }
        }
    }
    let Some(property) = property else {
        return Ok(fallback());
    };
    let record = store
        .type_payload(property.type_)
        .ok_or(KnownSymbolKeyError::InvalidType(property.type_))?;
    match record.data() {
        TypeData::Literal(literal) => match &literal.value {
            super::type_records::LiteralValue::String(name)
                if record.flags().intersects(TypeFlags::STRING_LITERAL) =>
            {
                Ok(EscapedName::source(ts_ast::normalize_js_string(name)))
            }
            super::type_records::LiteralValue::Number(number)
                if record.flags().intersects(TypeFlags::NUMBER_LITERAL) =>
            {
                Ok(EscapedName::source(number.to_string()))
            }
            _ if record
                .flags()
                .intersects(TypeFlags::STRING_LITERAL | TypeFlags::NUMBER_LITERAL) =>
            {
                Err(KnownSymbolKeyError::InvalidType(property.type_))
            }
            _ => Ok(fallback()),
        },
        TypeData::UniqueEsSymbol(unique) => {
            let key = record
                .symbol()
                .ok_or(KnownSymbolKeyError::InvalidType(property.type_))?;
            let key_record = store
                .symbol(key)
                .ok_or(KnownSymbolKeyError::InvalidSymbol(key))?;
            let global_id = store
                .symbol_store()
                .assigned_global_symbol_id(key)
                .ok_or(KnownSymbolKeyError::InvalidSymbol(key))?;
            let suffix = unique
                .name
                .as_bytes()
                .strip_prefix(b"\xFE@")
                .and_then(|name| name.strip_prefix(key_record.name().as_bytes()))
                .and_then(|name| name.strip_prefix(b"@"));
            if record.flags() != TypeFlags::UNIQUE_ES_SYMBOL
                || record.object_flags() != ObjectFlags::NONE
                || record.alias().is_some()
                || store.get_merged_symbol(key) != Some(key)
                || suffix != Some(global_id.to_string().as_bytes())
            {
                return Err(KnownSymbolKeyError::InvalidType(property.type_));
            }
            Ok(unique.name.clone())
        }
        _ if record.flags().intersects(
            TypeFlags::STRING_LITERAL | TypeFlags::NUMBER_LITERAL | TypeFlags::UNIQUE_ES_SYMBOL,
        ) =>
        {
            Err(KnownSymbolKeyError::InvalidType(property.type_))
        }
        _ => Ok(fallback()),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum ComputedMemberKeyError {
    Unsupported(NodeRef),
    Invalid(NodeRef),
    Capacity(NodeRef),
}

/// A computed key whose value comes from an exact unique-symbol annotation.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) struct PlannedComputedMemberKey {
    pub(super) expression: NodeRef,
    pub(super) key_symbol: SemanticSymbolId,
    pub(super) type_node: NodeRef,
}

/// Plans a computed key without resolving its annotation or changing links.
#[cfg_attr(not(test), allow(dead_code))]
pub(super) fn plan_computed_member_key(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    name: NodeRef,
) -> Result<PlannedComputedMemberKey, ComputedMemberKeyError> {
    let invalid = || ComputedMemberKeyError::Invalid(name);
    let unsupported = || ComputedMemberKeyError::Unsupported(name);
    let record = preflight_node(store, host, name).map_err(|_| invalid())?;
    let NodeData::ComputedPropertyName(computed) = &record.data else {
        return Err(unsupported());
    };
    let expression = NodeRef::new(name.arena, name.file, computed.expression);
    let expression_record = preflight_node(store, host, expression).map_err(|_| invalid())?;
    if record.kind != SyntaxKind::ComputedPropertyName
        || record.flags.0 != 0
        || computed.facts != 0
        || expression_record.parent != Some(name.node)
        || expression_record.flags.0 != 0
    {
        return Err(invalid());
    }
    match &expression_record.data {
        NodeData::Identifier(identifier)
            if expression_record.kind == SyntaxKind::Identifier
                && identifier.flow_node.is_none()
                && !identifier.text.is_empty() => {}
        NodeData::PropertyAccessExpression(access)
            if expression_record.kind == SyntaxKind::PropertyAccessExpression
                && access.flow_node.is_none()
                && access.question_dot_token.is_none()
                && access.facts == 0 => {}
        _ => return Err(unsupported()),
    }
    let mut resolver = host.name_resolver_host(store).map_err(|_| invalid())?;
    let key_symbol = match resolver
        .resolve_entity_name(expression, SymbolFlags::VALUE)
        .map_err(|_| unsupported())?
    {
        Some(symbol) => store.get_merged_symbol(symbol).ok_or_else(invalid)?,
        None => computed_member_property_symbol(store, host, expression)?,
    };
    let key = store.symbol(key_symbol).ok_or_else(invalid)?;
    let declaration = key.value_declaration().ok_or_else(unsupported)?;
    let declaration_record = preflight_node(store, host, declaration).map_err(|_| invalid())?;
    if !host.symbol_matches(store, declaration, key_symbol)
        || key
            .declarations()
            .is_none_or(|declarations| declarations != [declaration])
        || key.check_flags().bits() & !CheckFlags::READONLY.bits() != 0
        || key.members().is_some()
        || key.exports().is_some()
        || key.export_symbol().is_some()
    {
        return Err(invalid());
    }
    let type_node = match &declaration_record.data {
        NodeData::VariableDeclaration(variable)
            if declaration_record.kind == SyntaxKind::VariableDeclaration
                && key.flags() == SymbolFlags::BLOCK_SCOPED_VARIABLE =>
        {
            if key.check_flags() != CheckFlags::NONE {
                return Err(invalid());
            }
            let parent = declaration_record.parent.ok_or_else(invalid)?;
            let parent = NodeRef::new(declaration.arena, declaration.file, parent);
            let parent_record = preflight_node(store, host, parent).map_err(|_| invalid())?;
            if parent_record.kind != SyntaxKind::VariableDeclarationList
                || parent_record.flags.0 & (1 << 1) == 0
            {
                return Err(unsupported());
            }
            variable.type_.ok_or_else(unsupported)?
        }
        NodeData::PropertyDeclaration(property)
            if declaration_record.kind == SyntaxKind::PropertyDeclaration
                && key.flags() == SymbolFlags::PROPERTY =>
        {
            let (arena, _) = host.source(declaration).ok_or_else(invalid)?;
            let parent = declaration_record.parent.ok_or_else(invalid)?;
            let parent = NodeRef::new(declaration.arena, declaration.file, parent);
            let parent_kind = store.source_node_kind(parent);
            if !ts_binder::canonical_has_syntactic_modifier(
                arena,
                declaration.node,
                SyntaxKind::ReadonlyKeyword,
            ) || !matches!(
                parent_kind,
                Some(SyntaxKind::InterfaceDeclaration | SyntaxKind::TypeLiteral)
            ) && !ts_binder::canonical_has_syntactic_modifier(
                arena,
                declaration.node,
                SyntaxKind::StaticKeyword,
            ) {
                return Err(unsupported());
            }
            property.type_.ok_or_else(unsupported)?
        }
        NodeData::PropertySignatureDeclaration(property)
            if declaration_record.kind == SyntaxKind::PropertySignature
                && key.flags() == SymbolFlags::PROPERTY =>
        {
            let (arena, _) = host.source(declaration).ok_or_else(invalid)?;
            if !ts_binder::canonical_has_syntactic_modifier(
                arena,
                declaration.node,
                SyntaxKind::ReadonlyKeyword,
            ) {
                return Err(unsupported());
            }
            property.type_
        }
        _ => return Err(unsupported()),
    };
    let type_node = NodeRef::new(declaration.arena, declaration.file, type_node);
    let annotation = preflight_node(store, host, type_node).map_err(|_| invalid())?;
    let NodeData::TypeOperatorNode(operator) = &annotation.data else {
        return Err(unsupported());
    };
    let operand = NodeRef::new(type_node.arena, type_node.file, operator.type_);
    let operand_record = preflight_node(store, host, operand).map_err(|_| invalid())?;
    if annotation.kind != SyntaxKind::TypeOperator
        || annotation.parent != Some(declaration.node)
        || annotation.flags.0 != 0
        || operator.operator != SyntaxKind::UniqueKeyword
        || operand_record.kind != SyntaxKind::SymbolKeyword
        || operand_record.parent != Some(type_node.node)
    {
        return Err(unsupported());
    }
    let plan = PlannedComputedMemberKey {
        expression,
        key_symbol,
        type_node,
    };
    plan_computed_key_declared_value(store, host, &plan)?;
    Ok(plan)
}

fn computed_member_property_symbol(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    expression: NodeRef,
) -> Result<SemanticSymbolId, ComputedMemberKeyError> {
    let invalid = || ComputedMemberKeyError::Invalid(expression);
    let unsupported = || ComputedMemberKeyError::Unsupported(expression);
    let record = preflight_node(store, host, expression).map_err(|_| invalid())?;
    let NodeData::PropertyAccessExpression(access) = &record.data else {
        return Err(unsupported());
    };
    let receiver = NodeRef::new(expression.arena, expression.file, access.expression);
    let name = NodeRef::new(expression.arena, expression.file, access.name);
    let name_record = preflight_node(store, host, name).map_err(|_| invalid())?;
    let receiver_record = preflight_node(store, host, receiver).map_err(|_| invalid())?;
    let NodeData::Identifier(identifier) = &name_record.data else {
        return Err(unsupported());
    };
    if name_record.kind != SyntaxKind::Identifier
        || name_record.parent != Some(expression.node)
        || name_record.flags.0 != 0
        || identifier.flow_node.is_some()
        || receiver_record.parent != Some(expression.node)
    {
        return Err(invalid());
    }
    let mut resolver = host.name_resolver_host(store).map_err(|_| invalid())?;
    let receiver_symbol = resolver
        .resolve_entity_name(receiver, SymbolFlags::VALUE)
        .map_err(|_| unsupported())?
        .and_then(|symbol| store.get_merged_symbol(symbol))
        .ok_or_else(unsupported)?;
    if store.symbol_node_links(receiver).is_some_and(|links| {
        links
            .resolved_symbol
            .is_some_and(|symbol| symbol != receiver_symbol)
    }) {
        return Err(invalid());
    }
    let receiver_symbol_record = store.symbol(receiver_symbol).ok_or_else(invalid)?;
    let receiver_value = store
        .value_symbol_links(receiver_symbol)
        .cloned()
        .unwrap_or_default();
    let receiver_type = store.type_node_links(receiver).cloned().unwrap_or_default();
    if receiver_value
        != (ValueSymbolLinks {
            resolved_type: receiver_value.resolved_type,
            ..ValueSymbolLinks::default()
        })
        || receiver_type
            != (TypeNodeLinks {
                resolved_type: receiver_type.resolved_type,
                ..TypeNodeLinks::default()
            })
        || receiver_value
            .resolved_type
            .zip(receiver_type.resolved_type)
            .is_some_and(|(value, expression)| value != expression)
    {
        return Err(invalid());
    }
    let cached_receiver = receiver_value.resolved_type.or(receiver_type.resolved_type);
    let (member_owner, table) = if receiver_symbol_record.flags().contains(SymbolFlags::CLASS) {
        if cached_receiver.is_some_and(|type_| {
            super::classes::authenticated_class_constructor_value(store, receiver_symbol)
                .is_none_or(|(value, _)| value != type_)
        }) {
            return Err(invalid());
        }
        (
            receiver_symbol,
            receiver_symbol_record.exports().ok_or_else(unsupported)?,
        )
    } else {
        let declaration = receiver_symbol_record
            .value_declaration()
            .ok_or_else(unsupported)?;
        let declaration_record = preflight_node(store, host, declaration).map_err(|_| invalid())?;
        let NodeData::VariableDeclaration(variable) = &declaration_record.data else {
            return Err(unsupported());
        };
        let annotation = variable.type_.ok_or_else(unsupported)?;
        let annotation = NodeRef::new(declaration.arena, declaration.file, annotation);
        let annotation_record = preflight_node(store, host, annotation).map_err(|_| invalid())?;
        let NodeData::TypeReferenceNode(reference) = &annotation_record.data else {
            return Err(unsupported());
        };
        if annotation_record.parent != Some(declaration.node) || reference.type_arguments.is_some()
        {
            return Err(unsupported());
        }
        let type_name = NodeRef::new(annotation.arena, annotation.file, reference.type_name);
        let type_owner = resolver
            .resolve_entity_name(type_name, SymbolFlags::TYPE)
            .map_err(|_| unsupported())?
            .and_then(|symbol| store.get_merged_symbol(symbol))
            .ok_or_else(unsupported)?;
        let owner = store.symbol(type_owner).ok_or_else(invalid)?;
        if !owner.flags().contains(SymbolFlags::INTERFACE)
            || owner.flags().contains(SymbolFlags::CLASS)
        {
            return Err(unsupported());
        }
        if cached_receiver.is_some_and(|type_| {
            store
                .declared_type_links(type_owner)
                .and_then(|links| links.declared_type)
                != Some(type_)
        }) {
            return Err(invalid());
        }
        (type_owner, owner.members().ok_or_else(unsupported)?)
    };
    let symbol = store
        .symbol_table(table)
        .ok_or_else(invalid)?
        .get_source(&identifier.text)
        .and_then(|symbol| store.get_merged_symbol(symbol))
        .ok_or_else(unsupported)?;
    if store.symbol(symbol).is_none_or(|symbol| {
        symbol.name().as_utf8() != Some(identifier.text.as_str())
            || symbol
                .parent()
                .and_then(|parent| store.get_merged_symbol(parent))
                != Some(member_owner)
    }) {
        return Err(invalid());
    }
    Ok(symbol)
}

/// Reads a planned key after its annotation has been resolved by the type query.
#[cfg_attr(not(test), allow(dead_code))]
pub(super) fn resolved_computed_member_key(
    store: &CanonicalTypeMapperStore,
    plan: &PlannedComputedMemberKey,
) -> Result<Option<(TypeId, EscapedName)>, ComputedMemberKeyError> {
    let invalid = || ComputedMemberKeyError::Invalid(plan.expression);
    let key = store.symbol(plan.key_symbol).ok_or_else(invalid)?;
    if !matches!(
        store.source_node_kind(plan.expression),
        Some(SyntaxKind::Identifier | SyntaxKind::PropertyAccessExpression)
    ) || store.source_node_kind(plan.type_node) != Some(SyntaxKind::TypeOperator)
        || store.get_merged_symbol(plan.key_symbol) != Some(plan.key_symbol)
    {
        return Err(invalid());
    }
    let annotation = store
        .type_node_links(plan.type_node)
        .cloned()
        .unwrap_or_default();
    let value = store
        .value_symbol_links(plan.key_symbol)
        .cloned()
        .unwrap_or_default();
    let expression = store
        .type_node_links(plan.expression)
        .cloned()
        .unwrap_or_default();
    if annotation
        != (TypeNodeLinks {
            resolved_type: annotation.resolved_type,
            ..TypeNodeLinks::default()
        })
        || value
            != (ValueSymbolLinks {
                resolved_type: value.resolved_type,
                ..ValueSymbolLinks::default()
            })
        || expression
            != (TypeNodeLinks {
                resolved_type: expression.resolved_type,
                ..TypeNodeLinks::default()
            })
        || store
            .symbol_node_links(plan.expression)
            .is_some_and(|links| {
                links
                    .resolved_symbol
                    .is_some_and(|symbol| symbol != plan.key_symbol)
            })
    {
        return Err(invalid());
    }
    let candidates = [
        annotation.resolved_type,
        value.resolved_type,
        expression.resolved_type,
    ];
    let Some(type_) = candidates.into_iter().flatten().next() else {
        return Ok(None);
    };
    if candidates
        .into_iter()
        .flatten()
        .any(|cached| cached != type_)
    {
        return Err(invalid());
    }
    let record = store.type_payload(type_).ok_or_else(invalid)?;
    let TypeData::UniqueEsSymbol(unique) = record.data() else {
        return Err(invalid());
    };
    let global_id = store
        .symbol_store()
        .assigned_global_symbol_id(plan.key_symbol)
        .ok_or_else(invalid)?;
    let suffix = unique
        .name
        .as_bytes()
        .strip_prefix(b"\xFE@")
        .and_then(|name| name.strip_prefix(key.name().as_bytes()))
        .and_then(|name| name.strip_prefix(b"@"));
    if record.flags() != TypeFlags::UNIQUE_ES_SYMBOL
        || record.object_flags() != ObjectFlags::NONE
        || record.alias().is_some()
        || record.symbol() != Some(plan.key_symbol)
        || store.get_merged_symbol(plan.key_symbol) != Some(plan.key_symbol)
        || suffix != Some(global_id.to_string().as_bytes())
    {
        return Err(invalid());
    }
    Ok(Some((type_, unique.name.clone())))
}

/// Interface key values use the same source proof as selected property reads.
fn plan_computed_key_declared_value(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    plan: &PlannedComputedMemberKey,
) -> Result<Option<DeclaredValuePlan>, ComputedMemberKeyError> {
    let invalid = || ComputedMemberKeyError::Invalid(plan.expression);
    let resolved = resolved_computed_member_key(store, plan)?;
    let declaration = store
        .symbol(plan.key_symbol)
        .and_then(ts_binder::semantic::Symbol::value_declaration)
        .ok_or_else(invalid)?;
    let declaration_record = preflight_node(store, host, declaration).map_err(|_| invalid())?;
    let parent = declaration_record.parent.ok_or_else(invalid)?;
    let parent = NodeRef::new(declaration.arena, declaration.file, parent);
    if preflight_node(store, host, parent)
        .map_err(|_| invalid())?
        .kind
        != SyntaxKind::InterfaceDeclaration
    {
        return Ok(None);
    }
    let value = plan_declared_value(store, host, plan.key_symbol).map_err(|_| invalid())?;
    if value.annotation != plan.type_node
        || value.readonly != Some(true)
        || resolved.is_some_and(|(type_, _)| {
            !store.source_direct_type_annotation_is_exact(value.annotation, type_)
        })
    {
        return Err(invalid());
    }
    Ok(Some(value))
}

fn preflight_planned_computed_key_value(
    store: &CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    plan: &PlannedComputedMemberKey,
) -> Result<Option<DeclaredValuePlan>, ComputedMemberKeyError> {
    let invalid = || ComputedMemberKeyError::Invalid(plan.expression);
    let expression = preflight_node(store, host, plan.expression).map_err(|_| invalid())?;
    let parent = expression.parent.ok_or_else(invalid)?;
    let name = NodeRef::new(plan.expression.arena, plan.expression.file, parent);
    if plan_computed_member_key(store, host, name).map_err(|_| invalid())? != *plan {
        return Err(invalid());
    }
    plan_computed_key_declared_value(store, host, plan)
}

/// Publishes the key value and expression only after all key caches pass validation.
#[cfg_attr(not(test), allow(dead_code))]
pub(super) fn publish_computed_member_key_links(
    store: &mut CanonicalTypeMapperStore,
    host: &DeclaredTypeHost<'_>,
    plan: &PlannedComputedMemberKey,
) -> Result<(TypeId, EscapedName), ComputedMemberKeyError> {
    let value = preflight_planned_computed_key_value(store, host, plan)?;
    let result = resolved_computed_member_key(store, plan)?
        .ok_or(ComputedMemberKeyError::Unsupported(plan.expression))?;
    let (type_, _) = &result;
    if !store.try_reserve_symbol_node_links(usize::from(
        store.symbol_node_links(plan.expression).is_none(),
    )) || !store.try_reserve_type_node_links(usize::from(
        store.type_node_links(plan.expression).is_none(),
    )) || !store.try_reserve_value_symbol_links(usize::from(
        store.value_symbol_links(plan.key_symbol).is_none(),
    )) || value.is_some()
        && !store.try_reserve_declared_value_provenance(usize::from(
            store.declared_value_provenance(plan.key_symbol).is_none(),
        ))
    {
        return Err(ComputedMemberKeyError::Capacity(plan.expression));
    }
    if let Some(value) = value {
        publish_declared_value(store, value, *type_)
            .map_err(|_| ComputedMemberKeyError::Invalid(plan.expression))?;
    } else {
        assert!(store.set_value_symbol_links(
            plan.key_symbol,
            ValueSymbolLinks {
                resolved_type: Some(*type_),
                ..ValueSymbolLinks::default()
            }
        ));
    }
    assert!(store.set_symbol_node_links(
        plan.expression,
        SymbolNodeLinks {
            resolved_symbol: Some(plan.key_symbol)
        }
    ));
    assert!(store.set_type_node_links(
        plan.expression,
        TypeNodeLinks {
            resolved_type: Some(*type_),
            ..TypeNodeLinks::default()
        }
    ));
    Ok(result)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum PropertyObjectKind {
    TypeLiteral,
    Interface,
    ObjectLiteral,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum TypeLiteralMemberPolicy {
    ClassAssignment,
    General,
    ConcreteIndexedAccess,
    GenericInterface,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(super) struct PlannedProperty {
    pub declaration: NodeRef,
    pub symbol: SemanticSymbolId,
    #[allow(dead_code)] // Retained for the next property-diagnostic range slice.
    pub name_node: NodeRef,
    pub type_node: NodeRef,
    pub optional: bool,
    pub readonly: bool,
    pub name: EscapedName,
}

/// A getter body belongs to its own deferred scope, not to the object initializer.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(super) struct PlannedObjectLiteralGetter {
    pub object: NodeRef,
    pub owner: SemanticSymbolId,
    pub property_index: usize,
    pub declaration: NodeRef,
    pub symbol: SemanticSymbolId,
    pub name_node: NodeRef,
    pub body: NodeRef,
    pub return_statement: NodeRef,
    pub return_expression: NodeRef,
    pub return_annotation: Option<NodeRef>,
}

/// Retained outside mutable symbol and signature caches after object publication.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(super) struct ObjectLiteralGetterOrigin {
    getter: PlannedObjectLiteralGetter,
    object_type: TypeId,
    object_plan: Arc<PropertyObjectPlan>,
}

impl ObjectLiteralGetterOrigin {
    pub(super) const fn symbol(&self) -> SemanticSymbolId {
        self.getter.symbol
    }

    pub(super) const fn object(&self) -> NodeRef {
        self.getter.object
    }

    pub(super) const fn object_type(&self) -> TypeId {
        self.object_type
    }

    pub(super) const fn declaration(&self) -> NodeRef {
        self.getter.declaration
    }

    pub(super) const fn return_expression(&self) -> NodeRef {
        self.getter.return_expression
    }
}

/// The body checker supplies this result only after it checks the real return expression.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) struct ObjectLiteralGetterReturnProof {
    symbol: SemanticSymbolId,
    signature: SignatureId,
    expression_type: TypeId,
    read_type: TypeId,
    expression_symbol: Option<SemanticSymbolId>,
}

impl ObjectLiteralGetterReturnProof {
    pub(super) const fn symbol(&self) -> SemanticSymbolId {
        self.symbol
    }

    pub(super) const fn signature(&self) -> SignatureId {
        self.signature
    }
}

/// All getter consumers share this proof and retain every checked type edge.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) struct ObjectLiteralGetterProjection {
    pub symbol: SemanticSymbolId,
    pub owner: SemanticSymbolId,
    pub object_type: TypeId,
    pub declaration: NodeRef,
    pub type_: Option<TypeId>,
    pub signature: Option<SignatureId>,
    pub checked_return: Option<TypeId>,
}

impl ObjectLiteralGetterProjection {
    pub(super) fn require_type(self) -> Result<TypeId, RelationUnavailable> {
        self.type_
            .ok_or(RelationUnavailable::UnresolvedPropertyType(self.symbol))
    }

    pub(super) fn type_edges(self) -> impl Iterator<Item = TypeId> {
        self.type_.into_iter().chain(
            self.checked_return
                .filter(|checked| Some(*checked) != self.type_),
        )
    }
}

/// The source chosen when this provider publishes an object-literal property clone.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) struct ObjectLiteralPropertyCloneOrigin {
    symbol: SemanticSymbolId,
    owner: NodeRef,
    source: SemanticSymbolId,
}

/// Keeps hidden computed members and their checked inputs on the original object.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(super) struct SourceComputedObjectLiteralOrigin {
    type_: TypeId,
    plan: PropertyObjectPlan,
    keys: Vec<super::source::CheckedSourceComputedObjectKey>,
    property_types: Vec<TypeId>,
    properties: Vec<SemanticSymbolId>,
    indexes: Vec<(super::IndexInfoId, TypeId)>,
}

impl SourceComputedObjectLiteralOrigin {
    pub(super) const fn type_id(&self) -> TypeId {
        self.type_
    }
    pub(super) const fn owner(&self) -> SemanticSymbolId {
        self.plan.symbol
    }

    pub(super) fn property_symbols(&self) -> &[SemanticSymbolId] {
        &self.properties
    }
}

impl ObjectLiteralPropertyCloneOrigin {
    pub(super) const fn symbol(&self) -> SemanticSymbolId {
        self.symbol
    }

    pub(super) const fn owner(&self) -> NodeRef {
        self.owner
    }

    pub(super) const fn source(&self) -> SemanticSymbolId {
        self.source
    }
}

/// One unbound object spread and its position among source-owned properties.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) struct PlannedObjectSpread {
    pub declaration: NodeRef,
    pub expression: NodeRef,
    pub property_index: usize,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ResolvedObjectProperty {
    name: EscapedName,
    type_: TypeId,
    readonly: bool,
    optional: bool,
}

/// One binder-owned shorthand assignment with an explicit default expression.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) struct PlannedObjectAssignmentShorthand {
    pub object: NodeRef,
    pub owner: SemanticSymbolId,
    pub declaration: NodeRef,
    pub symbol: SemanticSymbolId,
    pub name: NodeRef,
    pub initializer: NodeRef,
}

const fn source_property_check_flags(readonly: bool) -> CheckFlags {
    if readonly {
        CheckFlags::READONLY
    } else {
        CheckFlags::NONE
    }
}

fn full_interface_computed_property_expression(
    store: &CanonicalTypeMapperStore,
    property: &PlannedProperty,
) -> Option<NodeRef> {
    if !matches!(
        store.source_node_kind(property.declaration),
        Some(SyntaxKind::PropertyDeclaration | SyntaxKind::PropertySignature)
    ) || store.source_node_kind(property.name_node) != Some(SyntaxKind::ComputedPropertyName)
        || store.source_node_parent(property.name_node)
            != Some(SourceNodeParent::Parent(property.declaration))
    {
        return None;
    }
    let SourceNodeParent::Parent(owner) = store.source_node_parent(property.declaration)? else {
        return None;
    };
    if !matches!(
        store.source_node_kind(owner),
        Some(SyntaxKind::InterfaceDeclaration | SyntaxKind::TypeLiteral)
    ) {
        return None;
    }
    let children = store.source_direct_children(property.name_node)?;
    let [expression] = children.as_slice() else {
        return None;
    };
    matches!(
        store.source_node_kind(*expression),
        Some(SyntaxKind::Identifier | SyntaxKind::PropertyAccessExpression)
    )
    .then_some(*expression)
}

fn full_interface_computed_property_source(
    store: &CanonicalTypeMapperStore,
    property: &PlannedProperty,
) -> Option<(SemanticSymbolId, SemanticSymbolId)> {
    full_interface_computed_property_expression(store, property)?;
    let source = store.source_declaration_symbol(property.declaration)?;
    let early = store.symbol(source)?;
    let owner = early
        .parent()
        .and_then(|owner| store.get_merged_symbol(owner))?;
    let owner_record = store.symbol(owner)?;
    let raw_members = owner_record
        .members()
        .and_then(|table| store.symbol_table(table));
    let SourceNodeParent::Parent(owner_declaration) =
        store.source_node_parent(property.declaration)?
    else {
        return None;
    };
    let valid_owner = match store.source_node_kind(owner_declaration) {
        Some(SyntaxKind::InterfaceDeclaration) => {
            owner_record.flags().contains(SymbolFlags::INTERFACE)
        }
        Some(SyntaxKind::TypeLiteral) => {
            owner_record.flags() == SymbolFlags::TYPE_LITERAL
                && owner_record.name() == InternalSymbolName::Type.as_ref()
                && owner_record.declarations() == Some(&[owner_declaration][..])
                && owner_record.value_declaration().is_none()
                && owner_record.parent().is_none()
                && owner_record.exports().is_none()
                && owner_record.export_symbol().is_none()
        }
        _ => false,
    };
    let children = store.source_direct_children(property.declaration)?;
    let optional_count = children
        .iter()
        .filter(|child| store.source_node_kind(**child) == Some(SyntaxKind::QuestionToken))
        .count();
    let readonly_count = children
        .iter()
        .filter(|child| store.source_node_kind(**child) == Some(SyntaxKind::ReadonlyKeyword))
        .count();
    if early.flags()
        != SymbolFlags::PROPERTY
            | if property.optional {
                SymbolFlags::OPTIONAL
            } else {
                SymbolFlags::NONE
            }
        || early.check_flags() != CheckFlags::NONE
        || early.name() != InternalSymbolName::Computed.as_ref()
        || early.declarations() != Some(&[property.declaration][..])
        || early.value_declaration() != Some(property.declaration)
        || early.members().is_some()
        || early.exports().is_some()
        || early.export_symbol().is_some()
        || store.get_merged_symbol(source) != Some(source)
        || !valid_owner
        || owner_record.check_flags() != CheckFlags::NONE
        || owner_record.members().is_some() != raw_members.is_some()
        || owner_record
            .declarations()
            .is_none_or(|declarations| !declarations.contains(&owner_declaration))
        || store
            .source_declaration_symbol(owner_declaration)
            .and_then(|symbol| store.get_merged_symbol(symbol))
            != Some(owner)
        || store.source_direct_type_annotation(property.declaration) != Some(property.type_node)
        || optional_count != usize::from(property.optional)
        || readonly_count != usize::from(property.readonly)
        || raw_members.is_some_and(|table| table.iter().any(|(_, symbol)| symbol == source))
        || store
            .value_symbol_links(source)
            .is_some_and(|links| links != &ValueSymbolLinks::default())
    {
        return None;
    }
    Some((source, owner))
}

/// Checks the source property and its separate late symbol without resolving a type.
fn late_interface_property_name_type(
    store: &CanonicalTypeMapperStore,
    property: &PlannedProperty,
) -> Option<TypeId> {
    let (source, owner) = full_interface_computed_property_source(store, property)?;
    let record = store.symbol(property.symbol)?;
    let early = store.symbol(source)?;
    let links = store.value_symbol_links(property.symbol)?;
    let name_type = links.name_type?;
    let TypeData::UniqueEsSymbol(unique) = store.type_payload(name_type)?.data() else {
        return None;
    };
    let members = store
        .members_and_exports_links(owner)?
        .table(super::links::MembersOrExportsResolutionKind::ResolvedMembers)?;
    if property.symbol == source
        || record.flags() != early.flags() | SymbolFlags::TRANSIENT
        || record.check_flags() != CheckFlags::LATE | source_property_check_flags(property.readonly)
        || record.name() != property.name.as_ref()
        || unique.name.as_ref() != property.name.as_ref()
        || store
            .late_bound_links(source)
            .and_then(|links| links.late_symbol)
            != Some(property.symbol)
        || store.symbol_node_links(property.declaration)
            != Some(&SymbolNodeLinks {
                resolved_symbol: Some(property.symbol),
            })
        || links
            .resolved_type
            .is_some_and(|type_| store.type_payload(type_).is_none())
        || !super::structured_members::valid_late_bound_unique_symbol_member(
            store,
            owner,
            property.symbol,
            &[property.declaration],
            links,
            store.symbol_table(members),
        )
    {
        return None;
    }
    Some(name_type)
}

pub(super) fn valid_declared_property_check_flags(
    store: &CanonicalTypeMapperStore,
    property: &PlannedProperty,
) -> bool {
    store.symbol(property.symbol).is_some_and(|record| {
        if record.flags().contains(SymbolFlags::METHOD) {
            !property.readonly
                && if store.source_node_kind(property.name_node)
                    == Some(SyntaxKind::ComputedPropertyName)
                {
                    planned_declared_property_key(store, property).is_some()
                        && record.check_flags() == CheckFlags::LATE
                } else {
                    record.check_flags() == CheckFlags::NONE
                }
        } else if record.flags().intersects(SymbolFlags::ACCESSOR) {
            record.check_flags() == CheckFlags::NONE
        } else if full_interface_computed_property_expression(store, property).is_some() {
            late_interface_property_name_type(store, property).is_some()
        } else {
            record.check_flags() == source_property_check_flags(property.readonly)
        }
    })
}

pub(super) fn planned_declared_property_key<'store>(
    store: &'store CanonicalTypeMapperStore,
    property: &PlannedProperty,
) -> Option<EscapedNameRef<'store>> {
    let record = store.symbol(property.symbol)?;
    if record.name() != property.name.as_ref() {
        return None;
    }
    if store.source_node_kind(property.name_node) == Some(SyntaxKind::ComputedPropertyName) {
        if store.source_node_parent(property.name_node)
            != Some(SourceNodeParent::Parent(property.declaration))
        {
            return None;
        }
        if store.source_node_kind(property.declaration) == Some(SyntaxKind::MethodSignature) {
            let source = store.source_declaration_symbol(property.declaration)?;
            if !store
                .late_bound_method_sources(property.symbol)?
                .contains(&source)
            {
                return None;
            }
            let source = store.symbol(source)?;
            if !record.flags().contains(SymbolFlags::METHOD)
                || !record.name().is_late_bound()
                || source.value_declaration() != Some(property.declaration)
                || record.value_declaration() != Some(property.declaration)
                || declared_method_value_links(
                    store,
                    property.symbol,
                    store
                        .value_symbol_links(property.symbol)
                        .and_then(|links| links.resolved_type),
                )
                .is_none()
            {
                return None;
            }
        } else if full_interface_computed_property_expression(store, property).is_some() {
            late_interface_property_name_type(store, property)?;
        } else if !matches!(
            store.source_node_kind(property.declaration),
            Some(SyntaxKind::PropertyDeclaration | SyntaxKind::PropertySignature)
        ) || ![
            SyntaxKind::StringLiteral,
            SyntaxKind::NumericLiteral,
            SyntaxKind::NoSubstitutionTemplateLiteral,
        ]
        .into_iter()
        .any(|kind| {
            store
                .source_child_with_kind(property.name_node, kind)
                .is_some()
        }) || record.flags()
            != SymbolFlags::PROPERTY
                | if property.optional {
                    SymbolFlags::OPTIONAL
                } else {
                    SymbolFlags::NONE
                }
            || record
                .declarations()
                .is_none_or(|declarations| !declarations.contains(&property.declaration))
        {
            return None;
        }
    }
    Some(record.name())
}

fn expected_declared_property_links(
    store: &CanonicalTypeMapperStore,
    plan: &PropertyObjectPlan,
    property: &PlannedProperty,
    read_type: TypeId,
) -> Option<ValueSymbolLinks> {
    if store
        .symbol(property.symbol)?
        .flags()
        .contains(SymbolFlags::METHOD)
    {
        return declared_method_value_links(store, property.symbol, Some(read_type));
    }
    let write_type = match plan.accessor_write_type_node(property.symbol) {
        Some(annotation) => {
            let write_type = cached_planned_type_identity(store, annotation)?;
            (write_type != read_type).then_some(write_type)
        }
        None => None,
    };
    let name_type = if full_interface_computed_property_expression(store, property).is_some() {
        Some(late_interface_property_name_type(store, property)?)
    } else {
        None
    };
    Some(ValueSymbolLinks {
        resolved_type: Some(read_type),
        write_type,
        name_type,
        ..ValueSymbolLinks::default()
    })
}

