    #[test]
    fn inherited_generic_methods_compare_their_type_parameters_by_position() {
        let mut fixture = interface_fixture(
            concat!(
                "interface Base { map<Value>(value: Value): Value } ",
                "interface Derived extends Base { map<Value>(value: Value): Value }",
            ),
            3_894,
        );
        let globals = fixture.store.intrinsic_bootstrap().unwrap().globals;
        let locals = fixture.bound.locals(fixture.bound.source_file()).unwrap();
        let derived = fixture
            .store
            .symbol_table(locals)
            .and_then(|locals| locals.get_source("Derived"))
            .unwrap();
        fixture.store.merge_global_symbol(globals, derived).unwrap();
        let host = host(&fixture.parsed, &fixture.bound);
        let mut diagnostics = CanonicalCheckerDiagnostics::default();

        let type_ = CanonicalTypeQuery::new(
            &mut fixture.store,
            &host,
            CanonicalCheckerOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_declared_type_of_symbol(derived)
        .unwrap();

        let TypeData::Interface(interface) = fixture.store.type_payload(type_).unwrap().data()
        else {
            panic!("generic method inheritance must retain its interface payload")
        };
        assert_eq!(
            interface
                .reference
                .object
                .structured
                .properties
                .as_ref()
                .map(Vec::len),
            Some(1),
        );
        assert!(diagnostics.is_empty());
    }

    #[test]
    fn method_literal_priority_uses_only_the_written_parameter_node() {
        let members = concat!(
            "direct(value: 'fixed'): string; ",
            "returned(value: string): 'fixed'; ",
            "wrapped(value: ('fixed')): string; ",
            "aliased(value: Label): string; ",
            "union(value: 'fixed' | 'other'): string;",
        );
        for type_literal in [false, true] {
            let source = if type_literal {
                format!("interface Owner {{}} type Label = 'fixed'; type Shape = {{ {members} }};")
            } else {
                format!("type Label = 'fixed'; interface Shape {{ {members} }}")
            };
            let fixture = interface_fixture(&source, 3_955);
            let host = host(&fixture.parsed, &fixture.bound);
            let snapshot = |store: &CanonicalTypeMapperStore| {
                (
                    store.type_len(),
                    store.symbol_len(),
                    store.signature_len(),
                    store.mapper_len(),
                    store.type_alias_len(),
                    store.symbol_store().symbol_table_len(),
                    store.checker_link_allocated_lengths(),
                )
            };
            let before = snapshot(&fixture.store);
            let plan = if type_literal {
                let (literal, alias) = fixture
                    .parsed
                    .arena
                    .iter()
                    .find_map(|(node, record)| {
                        (record.kind == SyntaxKind::TypeLiteral).then(|| {
                            let parent = NodeRef::new(
                                fixture.parsed.arena.id(),
                                fixture.file,
                                record.parent.unwrap(),
                            );
                            (
                                NodeRef::new(fixture.parsed.arena.id(), fixture.file, node),
                                fixture.bound.symbol(parent).unwrap(),
                            )
                        })
                    })
                    .unwrap();
                plan_type_literal(&fixture.store, &host, literal, Some(alias)).unwrap()
            } else {
                plan_interface(&fixture.store, &host, fixture.symbol).unwrap()
            };

            assert_eq!(
                plan.methods
                    .iter()
                    .map(|method| method.flags)
                    .collect::<Vec<_>>(),
                [
                    SignatureFlags::HAS_LITERAL_TYPES,
                    SignatureFlags::NONE,
                    SignatureFlags::NONE,
                    SignatureFlags::NONE,
                    SignatureFlags::NONE,
                ],
            );
            let wrapped = plan.methods[2].parameters[0];
            assert_eq!(
                fixture.store.source_node_kind(wrapped.type_node),
                Some(SyntaxKind::ParenthesizedType),
            );
            assert_eq!(
                fixture.store.source_node_kind(wrapped.identity_node),
                Some(SyntaxKind::LiteralType),
            );
            for method in &plan.methods {
                assert_eq!(
                    fixture.bound.symbol(method.declaration),
                    Some(method.symbol)
                );
                assert!(fixture.store.value_symbol_links(method.symbol).is_none());
                assert!(fixture.store.signature_links(method.declaration).is_none());
                for parameter in &method.parameters {
                    assert!(fixture.store.type_node_links(parameter.type_node).is_none());
                    assert!(fixture.store.value_symbol_links(parameter.symbol).is_none());
                }
            }
            assert_eq!(snapshot(&fixture.store), before);
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Both owner states use the same real method cache and restoration.
    fn method_literal_priority_rejects_changed_flags_before_and_after_owner_completion() {
        use crate::semantic::{DeclaredTypeError, DeclaredTypeUnavailable};

        for complete_owner in [false, true] {
            let mut fixture = interface_fixture(
                concat!(
                    "interface Shape { ",
                    "run(value: 'fixed'): string; ",
                    "run(value: string): number; ",
                    "}",
                ),
                3_956,
            );
            let host = host(&fixture.parsed, &fixture.bound);
            let plan = plan_interface(&fixture.store, &host, fixture.symbol).unwrap();
            let method = plan.methods[0].symbol;
            assert_eq!(
                interface_method_value_state(&fixture.store, &plan),
                Ok(None)
            );
            let mut diagnostics = CanonicalCheckerDiagnostics::default();
            let callable = CanonicalTypeQuery::new(
                &mut fixture.store,
                &host,
                CanonicalCheckerOptions::default(),
                &mut diagnostics,
            )
            .unwrap()
            .get_type_of_interface_method(method)
            .unwrap();
            let owner = fixture
                .store
                .declared_type_links(fixture.symbol)
                .unwrap()
                .declared_type
                .unwrap();
            if complete_owner {
                assert_eq!(
                    CanonicalTypeQuery::new(
                        &mut fixture.store,
                        &host,
                        CanonicalCheckerOptions::default(),
                        &mut diagnostics,
                    )
                    .unwrap()
                    .get_declared_type_of_symbol(fixture.symbol),
                    Ok(owner),
                );
            }
            assert_eq!(
                fixture
                    .store
                    .type_payload(owner)
                    .unwrap()
                    .object_flags()
                    .contains(ObjectFlags::MEMBERS_RESOLVED),
                complete_owner,
            );
            let signatures = fixture
                .store
                .type_payload(callable)
                .unwrap()
                .data()
                .structured()
                .unwrap()
                .signatures
                .clone()
                .unwrap();
            assert_eq!(signatures.len(), 2);
            let nodes = fixture
                .parsed
                .arena
                .iter()
                .map(|(node, _)| NodeRef::new(fixture.parsed.arena.id(), fixture.file, node))
                .collect::<Vec<_>>();
            let symbols = nodes
                .iter()
                .filter_map(|node| fixture.bound.symbol(*node))
                .collect::<Vec<_>>();
            let snapshot = |store: &CanonicalTypeMapperStore| {
                (
                    implicit_property_state(store, &plan, owner),
                    nodes
                        .iter()
                        .map(|node| {
                            (
                                store.type_node_links(*node).cloned(),
                                store.signature_links(*node).cloned(),
                                store.symbol_node_links(*node).cloned(),
                            )
                        })
                        .collect::<Vec<_>>(),
                    symbols
                        .iter()
                        .map(|symbol| store.value_symbol_links(*symbol).cloned())
                        .collect::<Vec<_>>(),
                    signatures
                        .iter()
                        .map(|signature| store.signature(*signature).unwrap().flags())
                        .collect::<Vec<_>>(),
                )
            };
            let healthy = snapshot(&fixture.store);
            for (&signature, changed) in signatures
                .iter()
                .zip([SignatureFlags::NONE, SignatureFlags::HAS_LITERAL_TYPES])
            {
                let original = fixture.store.signature(signature).unwrap().flags();
                assert_ne!(original, changed);
                assert!(fixture.store.set_signature_flags(signature, changed));
                let damaged = snapshot(&fixture.store);
                let expected = DeclaredTypeError::Unavailable(
                    DeclaredTypeUnavailable::InvalidInterfaceDeclaration(plan.node),
                );
                for _ in 0..2 {
                    let mut query = CanonicalTypeQuery::new(
                        &mut fixture.store,
                        &host,
                        CanonicalCheckerOptions::default(),
                        &mut diagnostics,
                    )
                    .unwrap();
                    assert_eq!(
                        query.preflight_type_of_interface_method(method),
                        Err(expected)
                    );
                    assert_eq!(query.get_type_of_interface_method(method), Err(expected));
                    assert_eq!(snapshot(&fixture.store), damaged);
                    assert!(diagnostics.is_empty());
                }
                assert!(fixture.store.set_signature_flags(signature, original));
                assert_eq!(
                    CanonicalTypeQuery::new(
                        &mut fixture.store,
                        &host,
                        CanonicalCheckerOptions::default(),
                        &mut diagnostics,
                    )
                    .unwrap()
                    .get_type_of_interface_method(method),
                    Ok(callable),
                );
                assert_eq!(snapshot(&fixture.store), healthy);
            }
            assert!(diagnostics.is_empty());
        }
    }

    #[test]
    fn interface_method_overloads_share_one_property_and_keep_each_signature() {
        let fixture = interface_fixture(
            "interface Shape { run(value: string): number; run(...args: any[]): void }",
            3_766,
        );
        let host = host(&fixture.parsed, &fixture.bound);

        let plan = plan_interface(&fixture.store, &host, fixture.symbol).unwrap();

        assert_eq!(plan.properties.len(), 1);
        let [first, second] = plan.methods.as_slice() else {
            panic!("the method symbol must retain both overload declarations")
        };
        assert_eq!(first.symbol, second.symbol);
        assert_eq!(first.symbol, plan.properties[0].symbol);
        assert_ne!(first.declaration, second.declaration);
        assert_eq!(first.flags, SignatureFlags::NONE);
        assert_eq!(first.parameters.len(), 1);
        assert_eq!(second.flags, SignatureFlags::HAS_REST_PARAMETER);
        assert_eq!(
            fixture
                .store
                .symbol(first.symbol)
                .and_then(ts_binder::semantic::Symbol::declarations),
            Some([first.declaration, second.declaration].as_slice()),
        );
    }

    #[test]
    fn interface_method_overloads_publish_one_callable_and_replay_warm() {
        let mut fixture = global_array_augmentation_fixture(
            concat!(
                "interface Array<T> { (): any[]; } ",
                "interface Contract { ",
                "run(value: string): number; ",
                "run(...args: any[]): void; ",
                "}",
            ),
            3_776,
        );
        let locals = fixture
            .source_bound
            .locals(fixture.source_bound.source_file())
            .unwrap();
        let contract = fixture
            .store
            .symbol_table(locals)
            .and_then(|locals| locals.get_source("Contract"))
            .unwrap();
        let globals = fixture.store.intrinsic_bootstrap().unwrap().globals;
        fixture
            .store
            .merge_global_symbol(globals, contract)
            .unwrap();
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&fixture.library.arena, &fixture.library_bound),
                (&fixture.source.arena, &fixture.source_bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let plan = plan_interface(&fixture.store, &host, contract).unwrap();
        let flags = fixture.store.symbol(contract).unwrap().flags();
        let owner_type = get_declared_class_interface_or_type_parameter(
            &mut fixture.store,
            &host,
            contract,
            flags,
        )
        .unwrap()
        .unwrap();
        let (any, string, number, void) = {
            let bootstrap = fixture.store.intrinsic_bootstrap().unwrap();
            (
                bootstrap.any_type,
                bootstrap.string_type,
                bootstrap.number_type,
                bootstrap.void_type,
            )
        };
        let any_array = fixture.global_types.any_array_type;
        let mut resolved = Vec::new();
        for method in &plan.methods {
            let return_type = match fixture.store.source_node_kind(method.return_type) {
                Some(SyntaxKind::NumberKeyword) => number,
                Some(SyntaxKind::VoidKeyword) => void,
                _ => panic!("the method fixture has numeric and void returns"),
            };
            assert!(fixture.store.set_type_node_links(
                method.return_type,
                TypeNodeLinks {
                    resolved_type: Some(return_type),
                    ..TypeNodeLinks::default()
                },
            ));
            let mut parameter_types = Vec::new();
            for parameter in &method.parameters {
                let parameter_type = match fixture.store.source_node_kind(parameter.type_node) {
                    Some(SyntaxKind::StringKeyword) => string,
                    Some(SyntaxKind::ArrayType) => {
                        let NodeData::ArrayTypeNode(array) = &fixture
                            .source
                            .arena
                            .get(parameter.type_node.node)
                            .unwrap()
                            .data
                        else {
                            unreachable!("the rest annotation is an array type")
                        };
                        let element = NodeRef::new(
                            parameter.type_node.arena,
                            parameter.type_node.file,
                            array.element_type,
                        );
                        assert!(fixture.store.set_type_node_links(
                            element,
                            TypeNodeLinks {
                                resolved_type: Some(any),
                                ..TypeNodeLinks::default()
                            },
                        ));
                        any_array
                    }
                    _ => panic!("the method fixture has string and any-array parameters"),
                };
                assert!(fixture.store.set_type_node_links(
                    parameter.type_node,
                    TypeNodeLinks {
                        resolved_type: Some(parameter_type),
                        ..TypeNodeLinks::default()
                    },
                ));
                parameter_types.push(parameter_type);
            }
            resolved.push(ResolvedCallSignatureTypes {
                parameter_types,
                return_type,
            });
        }

        let method_types =
            publish_interface_method_values(&mut fixture.store, &plan, &resolved).unwrap();

        assert_eq!(method_types.len(), 2);
        assert_eq!(method_types[0], method_types[1]);
        let method_type = method_types[0];
        let method_record = fixture.store.type_payload(method_type).unwrap();
        let signatures = method_record
            .data()
            .structured()
            .and_then(|structured| structured.signatures.as_deref())
            .unwrap();
        assert_eq!(signatures.len(), 2);
        assert_eq!(
            fixture.store.signature(signatures[0]).unwrap().flags(),
            SignatureFlags::NONE,
        );
        assert_eq!(
            fixture
                .store
                .signature(signatures[0])
                .unwrap()
                .min_argument_count(),
            1,
        );
        assert_eq!(
            fixture.store.signature(signatures[1]).unwrap().flags(),
            SignatureFlags::HAS_REST_PARAMETER,
        );
        assert_eq!(
            fixture
                .store
                .signature(signatures[1])
                .unwrap()
                .min_argument_count(),
            0,
        );
        assert!(matches!(
            crate::semantic::callable_sets::validate_stored_callable_set(
                &fixture.store,
                method_type,
            ),
            crate::semantic::callable_sets::StoredCallableSetValidation::Valid { .. }
        ));

        let state = interface_state(&fixture.store, &plan, owner_type).unwrap();
        assert_eq!(state, PropertyObjectState::Shell(owner_type));
        assert_eq!(
            publish_declared_members(&mut fixture.store, &plan, state, &[method_type], &[], &[],),
            Ok(owner_type),
        );
        let warm = (
            fixture.store.type_len(),
            fixture.store.signature_len(),
            fixture.store.checker_link_allocated_lengths(),
        );
        assert_eq!(
            publish_interface_method_values(&mut fixture.store, &plan, &resolved),
            Ok(method_types),
        );
        assert_eq!(
            (
                fixture.store.type_len(),
                fixture.store.signature_len(),
                fixture.store.checker_link_allocated_lengths(),
            ),
            warm,
        );
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Prove both library overloads and every lazy owner boundary.
    fn default_library_array_concat_publishes_only_generic_declaration_overloads() {
        let library = parse_source_file(concat!(
            "interface IArguments {} ",
            "interface Array<T> { ",
            "concat(...items: ConcatArray<T>[]): T[]; ",
            "concat(...items: (T | ConcatArray<T>)[]): T[]; ",
            "untouched(): void; ",
            "} declare var Array: any; ",
            "interface ConcatArray<T> { ",
            "readonly length: number; readonly [index: number]: T; ",
            "join(separator?: string): string; ",
            "slice(start?: number, end?: number): T[]; ",
            "} ",
            "interface Object {} interface Function {} ",
            "interface String {} interface Number {} interface Boolean {} ",
            "interface RegExp {} interface ReadonlyArray<T> {} interface ThisType<T> {}",
        ));
        let source = parse_source_file("type Pair = [number, number];");
        assert!(library.diagnostics.is_empty(), "{:?}", library.diagnostics);
        assert!(source.diagnostics.is_empty(), "{:?}", source.diagnostics);
        let library_file = FileId::new(3_780);
        let source_file = FileId::new(3_781);
        let mut binder = CanonicalBinder::new();
        for (parsed, file, default_library) in [
            (&library, library_file, true),
            (&source, source_file, false),
        ] {
            binder
                .bind_source_file_with_facts(
                    &parsed.arena,
                    parsed.source_file,
                    file,
                    CanonicalSourceFileFacts::new_with_default_library(
                        EscapedName::source(format!("\"/array-concat-{}.ts\"", file.index())),
                        CanonicalSourceLanguage::TypeScript,
                        default_library,
                        default_library,
                        CanonicalModuleState::Script,
                    ),
                )
                .unwrap();
            binder
                .bind_typescript_declaration_slice(&parsed.arena, file)
                .unwrap();
        }
        let (symbols, mut files) = binder.finish().try_into_parts().unwrap();
        let library_bound = files.remove(&library_file).unwrap();
        let source_bound = files.remove(&source_file).unwrap();
        let mut store = CanonicalTypeMapperStore::from_symbol_store(symbols);
        for (parsed, file) in [(&library, library_file), (&source, source_file)] {
            assert!(
                store
                    .register_source_file(&parsed.arena, parsed.source_file, file)
                    .is_some()
            );
        }
        store
            .initialize_intrinsic_bootstrap(IntrinsicBootstrapOptions::default())
            .unwrap();
        let globals = store.intrinsic_bootstrap().unwrap().globals;
        let library_symbols = store
            .symbol_table(library_bound.locals(library_bound.source_file()).unwrap())
            .unwrap()
            .iter()
            .map(|(_, symbol)| symbol)
            .collect::<Vec<_>>();
        for symbol in library_symbols {
            store.merge_global_symbol(globals, symbol).unwrap();
        }
        let host = DeclaredTypeHost::new_after_global_merge(
            [
                (&library.arena, &library_bound),
                (&source.arena, &source_bound),
            ],
            GlobalMergeCompletion::for_test(CanonicalNameResolverOptions::default()),
        )
        .unwrap();
        let global_types =
            initialize_global_library_types(&mut store, &host, globals, false).unwrap();
        let pair = store
            .symbol_table(source_bound.locals(source_bound.source_file()).unwrap())
            .and_then(|locals| locals.get_source("Pair"))
            .unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let pair = CanonicalTypeQuery::new_with_global_types(
            &mut store,
            &host,
            &global_types,
            CanonicalCheckerOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_declared_type_of_symbol(pair)
        .unwrap();
        let receiver = store
            .create_canonical_array_type(&global_types, pair, false)
            .unwrap();
        let type_parameter = match store.type_payload(global_types.array_type).unwrap().data() {
            TypeData::Interface(interface) => interface
                .reference
                .resolved_type_arguments
                .as_ref()
                .unwrap()[0],
            _ => panic!("the global Array target must retain one generic parameter"),
        };
        let owner = store
            .type_payload(global_types.array_type)
            .and_then(TypeRecord::symbol)
            .and_then(|owner| store.get_merged_symbol(owner))
            .unwrap();
        let members = store.symbol(owner).unwrap().members().unwrap();
        let method = store
            .symbol_table(members)
            .and_then(|members| members.get_source("concat"))
            .unwrap();
        let untouched = store
            .symbol_table(members)
            .and_then(|members| members.get_source("untouched"))
            .unwrap();
        assert!(store.value_symbol_links(method).is_none());
        assert!(store.value_symbol_links(untouched).is_none());

        let method_type =
            materialize_global_array_concat_method(&mut store, &host, &global_types, receiver)
                .unwrap()
                .unwrap();

        let object = store.type_payload(method_type).unwrap();
        let signatures = object
            .data()
            .structured()
            .and_then(|structured| structured.signatures.as_deref())
            .unwrap();
        assert_eq!(signatures.len(), 2);
        let mut parameter_types = Vec::new();
        for signature in signatures {
            let record = store.signature(*signature).unwrap();
            assert_eq!(record.flags(), SignatureFlags::HAS_REST_PARAMETER);
            assert_eq!(record.min_argument_count(), 0);
            assert_eq!(record.resolved_return_type(), Some(global_types.array_type));
            let [parameter] = record.parameters() else {
                panic!("each Array.concat overload has one rest parameter")
            };
            let parameter_type = store
                .value_symbol_links(*parameter)
                .and_then(|links| links.resolved_type)
                .unwrap();
            let parameter_declaration = store
                .symbol(*parameter)
                .unwrap()
                .value_declaration()
                .unwrap();
            let parameter_annotation = store
                .source_direct_type_annotation(parameter_declaration)
                .unwrap();
            let return_annotation = store
                .source_direct_type_annotation(record.declaration().unwrap())
                .unwrap();
            assert_eq!(
                store
                    .type_node_links(parameter_annotation)
                    .and_then(|links| links.resolved_type),
                Some(parameter_type),
            );
            assert_eq!(
                store
                    .type_node_links(return_annotation)
                    .and_then(|links| links.resolved_type),
                Some(global_types.array_type),
            );
            assert_eq!(
                store.function_signature_return_annotation(*signature),
                Some((return_annotation, false)),
            );
            assert_eq!(
                store.callable_signature_parameter_types(*signature),
                Some([parameter_type].as_slice()),
            );
            parameter_types.push(parameter_type);
        }
        let first = store
            .canonical_array_reference(&global_types, parameter_types[0])
            .unwrap()
            .unwrap();
        let concat = validate_direct_generic_reference(&store, first.element_type).unwrap();
        assert_eq!(concat.type_arguments.as_slice(), &[type_parameter]);
        assert_ne!(type_parameter, pair);
        let (concat_parameter, concat_index, source_join, source_slice) = {
            let TypeData::Interface(interface) = store.type_payload(concat.target).unwrap().data()
            else {
                panic!("ConcatArray must retain its generic interface target")
            };
            assert!(interface.declared_members_resolved);
            let [index] = interface.declared_index_infos.as_deref().unwrap() else {
                panic!("ConcatArray must publish its numeric index signature")
            };
            let members = store
                .symbol_table(interface.declared_members.unwrap())
                .unwrap();
            assert_eq!(members.len(), 3);
            assert!(members.get(InternalSymbolName::Index.as_ref()).is_none());
            (
                interface
                    .reference
                    .resolved_type_arguments
                    .as_ref()
                    .unwrap()[0],
                *index,
                members.get_source("join").unwrap(),
                members.get_source("slice").unwrap(),
            )
        };
        let declared_index = store.index_info(concat_index).unwrap();
        assert_eq!(
            declared_index.key_type(),
            store.intrinsic_bootstrap().unwrap().number_type,
        );
        assert_eq!(declared_index.value_type(), concat_parameter);
        assert!(declared_index.is_readonly());
        for method in [source_join, source_slice] {
            let callable = store
                .value_symbol_links(method)
                .and_then(|links| links.resolved_type)
                .unwrap();
            let [signature] = store
                .type_payload(callable)
                .and_then(|record| record.data().structured())
                .and_then(|structured| structured.signatures.as_deref())
                .unwrap()
            else {
                panic!("ConcatArray methods must retain one source signature")
            };
            assert_eq!(store.signature(*signature).unwrap().min_argument_count(), 0);
        }
        let second = store
            .canonical_array_reference(&global_types, parameter_types[1])
            .unwrap()
            .unwrap();
        let TypeData::Union(union) = store.type_payload(second.element_type).unwrap().data() else {
            panic!("the second overload retains the element-or-ConcatArray union")
        };
        assert!(union.union.types.contains(&type_parameter));
        assert!(union.union.types.contains(&first.element_type));
        assert!(store.value_symbol_links(untouched).is_none());
        let TypeData::Interface(array) =
            store.type_payload(global_types.array_type).unwrap().data()
        else {
            panic!("the array target remains an interface")
        };
        assert!(!array.declared_members_resolved);
        assert!(matches!(
            crate::semantic::callable_sets::validate_stored_callable_set(&store, method_type),
            crate::semantic::callable_sets::StoredCallableSetValidation::Valid { .. }
        ));

        let concat_pair = store
            .create_direct_generic_reference_type(concat.target, &[pair])
            .unwrap();
        let array_target = super::super::instantiated_members::GenericInterfaceArrayTarget::new(
            global_types.array_type,
        );
        let concat_members = store
            .resolve_generic_interface_members(concat_pair, Some(array_target))
            .unwrap();
        let [length, join, slice] = concat_members.properties() else {
            panic!("ConcatArray must preserve length, join, and slice in source order")
        };
        assert_eq!(
            store.symbol(*length).unwrap().name().as_utf8(),
            Some("length")
        );
        assert_eq!(*join, source_join);
        assert_ne!(*slice, source_slice);
        let [instantiated_index] = store
            .type_payload(concat_pair)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.index_infos.as_deref())
            .unwrap()
        else {
            panic!("ConcatArray<Pair> must publish its numeric index")
        };
        assert_eq!(
            store.index_info(*instantiated_index).unwrap().value_type(),
            pair
        );
        let specialized_slice = store
            .resolve_generic_interface_property(concat_pair, "slice", Some(array_target))
            .unwrap()
            .unwrap()
            .type_id();
        let [slice_signature] = store
            .type_payload(specialized_slice)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.signatures.as_deref())
            .unwrap()
        else {
            panic!("the instantiated slice must retain its source signature")
        };
        let slice_return = store
            .signature(*slice_signature)
            .and_then(super::super::signatures::Signature::resolved_return_type)
            .unwrap();
        assert_eq!(
            store
                .canonical_array_reference(&global_types, slice_return)
                .unwrap()
                .unwrap()
                .element_type,
            pair,
        );

        let warm = (
            store.type_len(),
            store.signature_len(),
            store.symbol_len(),
            store.index_info_len(),
            store.checker_link_allocated_lengths(),
        );
        assert_eq!(
            materialize_global_array_concat_method(&mut store, &host, &global_types, receiver),
            Ok(Some(method_type)),
        );
        assert_eq!(
            (
                store.type_len(),
                store.signature_len(),
                store.symbol_len(),
                store.index_info_len(),
                store.checker_link_allocated_lengths(),
            ),
            warm,
        );
        assert!(diagnostics.is_empty());
    }

    struct DateUnionFixture<'arena> {
        context: crate::semantic::CanonicalCheckerContext<'arena>,
        sources: Vec<(&'arena ts_ast::NodeArena, BoundFile)>,
        date: SemanticSymbolId,
        type_: TypeId,
        marker: SemanticSymbolId,
        sibling: SemanticSymbolId,
    }

    fn date_union_file_facts(file: FileId, default_library: bool) -> CanonicalSourceFileFacts {
        CanonicalSourceFileFacts::new_with_default_library(
            EscapedName::source(format!("\"/lib/date-union-{}.d.ts\"", file.index())),
            CanonicalSourceLanguage::TypeScript,
            true,
            default_library,
            CanonicalModuleState::Script,
        )
    }

    fn date_union_fixture<'arena>(
        library: &'arena ParseResult,
        augmentation: &'arena ParseResult,
        default_library: bool,
    ) -> DateUnionFixture<'arena> {
        let mut binder = CanonicalBinder::new();
        let mut arenas = Vec::new();
        for (parsed, file) in [
            (library, FileId::new(9_950)),
            (augmentation, FileId::new(9_951)),
        ] {
            assert!(parsed.diagnostics.is_empty());
            binder
                .bind_source_file_with_facts(
                    &parsed.arena,
                    parsed.source_file,
                    file,
                    date_union_file_facts(file, default_library),
                )
                .unwrap();
            binder
                .bind_typescript_declaration_slice(&parsed.arena, file)
                .unwrap();
            arenas.push((file, &parsed.arena));
        }
        let mut context = crate::semantic::CanonicalCheckerContext::new(
            binder.finish(),
            arenas.clone(),
            CanonicalCheckerOptions {
                intrinsic: IntrinsicBootstrapOptions {
                    strict_null_checks: true,
                    exact_optional_property_types: false,
                },
                ..CanonicalCheckerOptions::default()
            },
        )
        .unwrap();
        let sources: Vec<_> = arenas
            .iter()
            .map(|(file, arena)| (*arena, context.file(*file).unwrap().1.clone()))
            .collect();
        let date = context
            .store()
            .symbol_table(context.store().intrinsic_bootstrap().unwrap().globals)
            .and_then(|globals| globals.get_source("Date"))
            .and_then(|symbol| context.store().get_merged_symbol(symbol))
            .unwrap();
        let type_ = {
            let host = DeclaredTypeHost::new_after_global_merge(
                sources.iter().map(|(arena, bound)| (*arena, bound)),
                GlobalMergeCompletion::for_test(context.options().name_resolution),
            )
            .unwrap();
            context
                .store_mut_for_test()
                .get_declared_type_of_symbol(&host, date)
                .unwrap()
        };
        let table = context
            .store()
            .symbol(date)
            .unwrap()
            .members()
            .and_then(|members| context.store().symbol_table(members))
            .unwrap();
        let marker = context
            .store()
            .get_merged_symbol(table.get_source("toISOString").unwrap())
            .unwrap();
        let sibling = context
            .store()
            .get_merged_symbol(table.get_source("toJSON").unwrap())
            .unwrap();
        DateUnionFixture {
            context,
            sources,
            date,
            type_,
            marker,
            sibling,
        }
    }

    fn publish_date_union_marker(fixture: &mut DateUnionFixture<'_>) -> TypeId {
        let host = DeclaredTypeHost::new_after_global_merge(
            fixture.sources.iter().map(|(arena, bound)| (*arena, bound)),
            GlobalMergeCompletion::for_test(fixture.context.options().name_resolution),
        )
        .unwrap();
        let mut diagnostics = CanonicalCheckerDiagnostics::default();
        let callable = CanonicalTypeQuery::new(
            fixture.context.store_mut_for_test(),
            &host,
            crate::semantic::type_nodes::CanonicalTypeQueryOptions::default(),
            &mut diagnostics,
        )
        .unwrap()
        .get_type_of_interface_method(fixture.marker)
        .unwrap();
        assert!(diagnostics.is_empty());
        callable
    }

    const DATE_UNION_LIBRARY: &str = concat!(
        "interface Date { toISOString(): string; } ",
        "interface DateConstructor { new(): Date; readonly prototype: Date; } ",
        "declare var Date: DateConstructor;",
    );
    const DATE_UNION_AUGMENTATION: &str = "interface Date { toJSON(key?: any): string; }";

    fn assert_date_union_rejection_without_writes(
        fixture: &mut DateUnionFixture<'_>,
        expected: crate::semantic::bootstrap::LiteralTypeCacheError,
    ) {
        use crate::semantic::bootstrap::LiteralTypeCacheError;

        let store = fixture.context.store_mut_for_test();
        let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
        let before = (
            store.type_len(),
            store.signature_len(),
            store.symbol_len(),
            store.mapper_len(),
            store.index_info_len(),
            store.checker_link_allocated_lengths(),
        );
        let graph = validate_resolved_declared_property_type_graph(store, fixture.type_);
        match expected {
            LiteralTypeCacheError::UnsupportedUnionConstituent(_) => {
                assert!(matches!(graph, DeclaredPropertyTypeGraphValidation::Opaque));
            }
            LiteralTypeCacheError::InvalidCachedUnion(_) => {
                assert!(matches!(
                    graph,
                    DeclaredPropertyTypeGraphValidation::Malformed
                ));
            }
            _ => panic!("the Date graph must distinguish excluded shapes from invalid caches"),
        }
        assert_eq!(
            store.expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal),
            Err(expected),
        );
        assert_eq!(
            (
                store.type_len(),
                store.signature_len(),
                store.symbol_len(),
                store.mapper_len(),
                store.index_info_len(),
                store.checker_link_allocated_lengths(),
            ),
            before,
        );
    }

    fn assert_date_union_identity_without_member_writes(
        fixture: &mut DateUnionFixture<'_>,
    ) -> TypeId {
        assert_date_union_identity(fixture, None)
    }

    fn assert_date_union_identity(
        fixture: &mut DateUnionFixture<'_>,
        global_types: Option<&CanonicalGlobalTypes>,
    ) -> TypeId {
        let store = fixture.context.store_mut_for_test();
        let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
        let mut constituents = [fixture.type_, undefined];
        constituents.sort_unstable();
        let cached = store
            .intrinsic_bootstrap()
            .unwrap()
            .cached_union_type(&constituents);
        let before = (
            store.type_len(),
            store.signature_len(),
            store.symbol_len(),
            store.mapper_len(),
            store.index_info_len(),
            store.checker_link_allocated_lengths(),
        );
        let query = |store: &mut CanonicalTypeMapperStore| match global_types {
            Some(global_types) => store.expression_union_type_with_global_types(
                global_types,
                &constituents,
                UnionReduction::Literal,
            ),
            None => store.expression_union_type(&constituents, UnionReduction::Literal),
        };
        let union = query(store).unwrap();
        assert_eq!(
            store.validate_canonical_union_metadata(union, &constituents),
            Ok(()),
        );
        assert!(cached.is_none_or(|cached| cached == union));
        assert_eq!(query(store), Ok(union));
        assert_eq!(
            (
                store.type_len(),
                store.signature_len(),
                store.symbol_len(),
                store.mapper_len(),
                store.index_info_len(),
                store.checker_link_allocated_lengths(),
            ),
            (
                before.0 + usize::from(cached.is_none()),
                before.1,
                before.2,
                before.3,
                before.4,
                before.5,
            ),
        );
        union
    }

    fn assert_date_union_identity_after_method_query(fixture: &mut DateUnionFixture<'_>) {
        let optional = assert_date_union_identity_without_member_writes(fixture);
        publish_date_union_marker(fixture);
        assert_eq!(
            assert_date_union_identity_without_member_writes(fixture),
            optional,
        );
        let store = fixture.context.store_mut_for_test();
        let null = store.intrinsic_bootstrap().unwrap().null_type;
        let mut constituents = [fixture.type_, null];
        constituents.sort_unstable();
        let before = (
            store.type_len(),
            store.signature_len(),
            store.symbol_len(),
            store.checker_link_allocated_lengths(),
        );
        let nullable = store
            .expression_union_type(&constituents, UnionReduction::Literal)
            .unwrap();
        assert_ne!(nullable, optional);
        assert_eq!(
            store.validate_canonical_union_metadata(nullable, &constituents),
            Ok(()),
        );
        assert_eq!(
            (
                store.type_len(),
                store.signature_len(),
                store.symbol_len(),
                store.checker_link_allocated_lengths(),
            ),
            (before.0 + 1, before.1, before.2, before.3),
        );
    }

    fn assert_date_marker_cache_guard(fixture: &mut DateUnionFixture<'_>) {
        use crate::semantic::bootstrap::LiteralTypeCacheError;

        let malformed = LiteralTypeCacheError::InvalidCachedUnion(fixture.type_);
        assert_date_union_identity_without_member_writes(fixture);
        let store = fixture.context.store_mut_for_test();
        let marker_links = store
            .value_symbol_links(fixture.marker)
            .cloned()
            .unwrap_or_default();
        let number = store.intrinsic_bootstrap().unwrap().number_type;
        assert!(store.set_value_symbol_links(
            fixture.marker,
            ValueSymbolLinks {
                resolved_type: Some(number),
                ..ValueSymbolLinks::default()
            },
        ));
        assert_date_union_rejection_without_writes(fixture, malformed);
        assert!(
            fixture
                .context
                .store_mut_for_test()
                .set_value_symbol_links(fixture.marker, marker_links)
        );
        assert_date_union_identity_without_member_writes(fixture);
        assert!(
            fixture
                .context
                .store()
                .value_symbol_links(fixture.sibling)
                .is_none()
        );
    }

    #[test]
    fn date_unions_keep_generic_siblings_cold_without_hiding_invalid_caches() {
        use crate::semantic::bootstrap::LiteralTypeCacheError;

        let library = parse_source_file(DATE_UNION_LIBRARY);
        for method in [
            "extra<T>(value: T): T;",
            "extra<T, U>(first: T, second: U): T;",
        ] {
            let source = format!(
                "{DATE_UNION_AUGMENTATION} interface Date {{ {method} }} {}",
                "interface DateConstructor { new(value: string): Date; }",
            );
            let augmentation = parse_source_file(&source);
            for warm in [false, true] {
                let mut fixture = date_union_fixture(&library, &augmentation, true);
                if warm {
                    publish_date_union_marker(&mut fixture);
                }
                assert_date_marker_cache_guard(&mut fixture);
                let malformed = LiteralTypeCacheError::InvalidCachedUnion(fixture.type_);
                let store = fixture.context.store_mut_for_test();
                let constructor = store
                    .symbol_table(store.intrinsic_bootstrap().unwrap().globals)
                    .and_then(|globals| globals.get_source("DateConstructor"))
                    .and_then(|symbol| store.get_merged_symbol(symbol))
                    .unwrap();
                let declarations = store
                    .symbol(constructor)
                    .unwrap()
                    .declarations()
                    .unwrap()
                    .to_vec();
                assert_eq!(declarations.len(), 2);
                assert_ne!(declarations[0], declarations[1]);
                assert!(store.set_symbol_declarations(
                    constructor,
                    Some(vec![declarations[0], declarations[0]]),
                    None,
                ));
                assert_date_union_rejection_without_writes(&mut fixture, malformed);
                assert!(
                    fixture
                        .context
                        .store_mut_for_test()
                        .set_symbol_declarations(constructor, Some(declarations), None,)
                );
                assert_date_union_identity_without_member_writes(&mut fixture);
                if !warm {
                    assert_date_union_identity_after_method_query(&mut fixture);
                }
            }
        }
    }

    #[test]
    fn date_unions_keep_nonmethod_siblings_cold_without_hiding_marker_caches() {
        let library = parse_source_file(DATE_UNION_LIBRARY);
        for member in [
            "readonly label: string;",
            "get value(): number;",
            "[index: number]: string;",
            "(): string;",
            "new(): Date;",
        ] {
            let source = format!("{DATE_UNION_AUGMENTATION} interface Date {{ {member} }}");
            let augmentation = parse_source_file(&source);
            for warm in [false, true] {
                let mut fixture = date_union_fixture(&library, &augmentation, true);
                if warm {
                    publish_date_union_marker(&mut fixture);
                }
                assert_date_marker_cache_guard(&mut fixture);
                if !warm {
                    assert_date_union_identity_after_method_query(&mut fixture);
                }
            }
        }
    }

    #[test]
    fn date_unions_keep_es2015_computed_siblings_cold_without_member_writes() {
        let well_known = include_str!("../../../ts_bundled/libs/lib.es2015.symbol.wellknown.d.ts");
        let parsed = parse_source_file(well_known);
        assert!(parsed.diagnostics.is_empty());
        let range = parsed
            .arena
            .iter()
            .find_map(|(_, record)| {
                let NodeData::InterfaceDeclaration(interface) = &record.data else {
                    return None;
                };
                let NodeData::Identifier(name) = &parsed.arena.get(interface.name)?.data else {
                    return None;
                };
                (name.text == "Date").then_some(record.range)
            })
            .expect("the ES2015 library must contain its real Date declaration");
        let augmentation_source = format!(
            "{DATE_UNION_AUGMENTATION}\n{}",
            &well_known[range.start.get() as usize..range.end.get() as usize],
        );
        let library_source = format!(
            "{DATE_UNION_LIBRARY}\n{}",
            concat!(
                "interface SymbolConstructor { readonly toPrimitive: unique symbol; } ",
                "declare var Symbol: SymbolConstructor;",
            ),
        );
        let library = parse_source_file(&library_source);
        let augmentation = parse_source_file(&augmentation_source);
        let computed_declaration = augmentation
            .arena
            .iter()
            .find_map(|(node, record)| {
                let NodeData::MethodSignatureDeclaration(method) = &record.data else {
                    return None;
                };
                (augmentation.arena.get(method.name)?.kind == SyntaxKind::ComputedPropertyName)
                    .then_some(NodeRef::new(
                        augmentation.arena.id(),
                        FileId::new(9_951),
                        node,
                    ))
            })
            .expect("the real Date declaration must retain its computed methods");
        for warm in [false, true] {
            let mut fixture = date_union_fixture(&library, &augmentation, true);
            assert_eq!(
                fixture
                    .context
                    .store()
                    .source_computed_member_count(fixture.date),
                Some(4)
            );
            if warm {
                publish_date_union_marker(&mut fixture);
            }
            assert_date_marker_cache_guard(&mut fixture);
            let store = fixture.context.store_mut_for_test();
            let computed = store
                .source_declaration_symbol(computed_declaration)
                .unwrap();
            assert!(store.set_late_bound_links(
                computed,
                crate::semantic::links::LateBoundLinks {
                    late_symbol: Some(fixture.marker)
                },
            ));
            let malformed = crate::semantic::bootstrap::LiteralTypeCacheError::InvalidCachedUnion(
                fixture.type_,
            );
            assert_date_union_rejection_without_writes(&mut fixture, malformed);
            assert!(
                fixture.context.store_mut_for_test().set_late_bound_links(
                    computed,
                    crate::semantic::links::LateBoundLinks::default(),
                )
            );
            assert_date_union_identity_without_member_writes(&mut fixture);
            if !warm {
                assert_date_union_identity_after_method_query(&mut fixture);
            }
        }
    }

    #[test]
    fn date_unions_reject_malformed_cold_thisless_member_caches() {
        let library = parse_source_file(DATE_UNION_LIBRARY);
        let augmentation = parse_source_file(DATE_UNION_AUGMENTATION);
        let mut fixture = date_union_fixture(&library, &augmentation, true);
        assert_date_union_identity_without_member_writes(&mut fixture);
        let type_ = fixture.type_;
        let members = fixture
            .context
            .store()
            .symbol(fixture.date)
            .unwrap()
            .members();
        assert!(
            fixture
                .context
                .store_mut_for_test()
                .set_interface_declared_members(type_, false, members, None, None, None),
        );
        for _ in 0..2 {
            assert_date_union_rejection_without_writes(
                &mut fixture,
                crate::semantic::bootstrap::LiteralTypeCacheError::InvalidCachedUnion(type_),
            );
        }
        assert!(
            fixture
                .context
                .store_mut_for_test()
                .set_interface_declared_members(type_, false, None, None, None, None),
        );
        assert_date_union_identity_without_member_writes(&mut fixture);
    }

    #[test]
    fn date_unions_reject_replaced_missing_and_extra_cold_members() {
        let library = parse_source_file(DATE_UNION_LIBRARY);
        let augmentation = parse_source_file(concat!(
            "interface Date { toJSON(key?: any): string; } ",
            "interface Date { readonly label: string; }",
        ));
        for poison in 0..3 {
            let mut fixture = date_union_fixture(&library, &augmentation, true);
            let union = assert_date_union_identity_without_member_writes(&mut fixture);
            let store = fixture.context.store_mut_for_test();
            let original = store.symbol(fixture.date).unwrap().members().unwrap();
            let entries = store
                .symbol_table(original)
                .unwrap()
                .iter()
                .map(|(name, member)| (name.to_owned(), member))
                .collect::<Vec<_>>();
            let poisoned = store.alloc_symbol_table();
            for (name, member) in entries {
                if poison == 1 && name.as_utf8() == Some("label") {
                    continue;
                }
                let member = if poison == 0 && name.as_utf8() == Some("label") {
                    fixture.sibling
                } else {
                    member
                };
                assert_eq!(store.insert_symbol(poisoned, name, member), Some(None));
            }
            if poison == 2 {
                assert_eq!(
                    store.insert_symbol(poisoned, EscapedName::source("extra"), fixture.sibling),
                    Some(None),
                );
            }
            assert!(store.set_symbol_relationships(fixture.date, Some(poisoned), None, None, None));
            let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
            let before = (
                store.type_len(),
                store.symbol_len(),
                store.symbol_store().symbol_table_len(),
                store.signature_len(),
                store.checker_link_allocated_lengths(),
            );
            for _ in 0..2 {
                assert!(
                    store
                        .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
                        .is_err(),
                    "table case {poison}",
                );
                assert_eq!(
                    (
                        store.type_len(),
                        store.symbol_len(),
                        store.symbol_store().symbol_table_len(),
                        store.signature_len(),
                        store.checker_link_allocated_lengths(),
                    ),
                    before,
                );
            }
            assert!(store.set_symbol_relationships(fixture.date, Some(original), None, None, None));
            assert_eq!(
                assert_date_union_identity_without_member_writes(&mut fixture),
                union,
            );
        }
    }

    #[test]
    fn date_unions_reject_composite_annotation_cache_substitution() {
        let library = parse_source_file(DATE_UNION_LIBRARY);
        for (annotation_text, annotation_kind) in [
            ("string[]", SyntaxKind::ArrayType),
            ("Date", SyntaxKind::TypeReference),
        ] {
            let augmentation = parse_source_file(&format!(
                "{DATE_UNION_AUGMENTATION} interface Date {{ readonly label: {annotation_text}; }}",
            ));
            for published_property in [false, true] {
                let mut fixture = date_union_fixture(&library, &augmentation, true);
                let union = assert_date_union_identity_without_member_writes(&mut fixture);
                let store = fixture.context.store_mut_for_test();
                let property = store
                    .symbol(fixture.date)
                    .and_then(ts_binder::semantic::Symbol::members)
                    .and_then(|table| store.symbol_table(table))
                    .and_then(|members| members.get_source("label"))
                    .and_then(|symbol| store.get_merged_symbol(symbol))
                    .unwrap();
                let annotation = store
                    .symbol(property)
                    .and_then(ts_binder::semantic::Symbol::value_declaration)
                    .and_then(|declaration| store.source_direct_type_annotation(declaration))
                    .unwrap();
                assert_eq!(store.source_node_kind(annotation), Some(annotation_kind));
                let number = store.intrinsic_bootstrap().unwrap().number_type;
                let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
                assert!(store.set_type_node_links(
                    annotation,
                    TypeNodeLinks {
                        resolved_type: Some(number),
                        ..TypeNodeLinks::default()
                    },
                ));
                if published_property {
                    assert!(store.set_value_symbol_links(
                        property,
                        ValueSymbolLinks {
                            resolved_type: Some(number),
                            ..ValueSymbolLinks::default()
                        },
                    ));
                }
                let before = (
                    store.type_len(),
                    store.symbol_len(),
                    store.signature_len(),
                    store.checker_link_allocated_lengths(),
                );
                for _ in 0..2 {
                    assert!(
                        store
                            .expression_union_type(
                                &[fixture.type_, undefined],
                                UnionReduction::Literal
                            )
                            .is_err(),
                        "{annotation_text} substituted with number, published property: {published_property}",
                    );
                    assert_eq!(
                        (
                            store.type_len(),
                            store.symbol_len(),
                            store.signature_len(),
                            store.checker_link_allocated_lengths(),
                        ),
                        before,
                    );
                }
                assert!(store.set_type_node_links(annotation, TypeNodeLinks::default()));
                if published_property {
                    assert!(store.set_value_symbol_links(property, ValueSymbolLinks::default()));
                }
                assert_eq!(
                    assert_date_union_identity_without_member_writes(&mut fixture),
                    union,
                );
            }
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Check real annotation queries and their exact cache identities.
    fn date_unions_preserve_real_array_and_reference_annotation_queries() {
        let library = parse_source_file(&format!(
            "{DATE_UNION_LIBRARY} interface Array<T> {{}} interface ReadonlyArray<T> {{}}",
        ));
        for annotation_text in ["string[]", "Date"] {
            let augmentation = parse_source_file(&format!(
                "{DATE_UNION_AUGMENTATION} interface Date {{ readonly label: {annotation_text}; }}",
            ));
            let mut fixture = date_union_fixture(&library, &augmentation, true);
            let globals = fixture.context.global_types().clone();
            let union = assert_date_union_identity(&mut fixture, Some(&globals));
            let store = fixture.context.store();
            let label = store
                .symbol(fixture.date)
                .and_then(ts_binder::semantic::Symbol::members)
                .and_then(|members| store.symbol_table(members))
                .and_then(|members| members.get_source("label"))
                .unwrap();
            let annotation = store
                .symbol(label)
                .and_then(ts_binder::semantic::Symbol::value_declaration)
                .and_then(|declaration| store.source_direct_type_annotation(declaration))
                .unwrap();
            let type_ = fixture.context.get_type_from_type_node(annotation).unwrap();
            if annotation_text == "string[]" {
                let store = fixture.context.store();
                let array = store
                    .canonical_array_reference(fixture.context.global_types(), type_)
                    .unwrap()
                    .unwrap();
                assert_eq!(
                    array.element_type,
                    store.intrinsic_bootstrap().unwrap().string_type
                );
            } else {
                assert_eq!(type_, fixture.type_);
            }
            assert_eq!(
                assert_date_union_identity(&mut fixture, Some(&globals)),
                union,
            );
            let before = (
                fixture.context.store().type_len(),
                fixture.context.store().symbol_len(),
                fixture.context.store().signature_len(),
                fixture.context.store().checker_link_allocated_lengths(),
            );
            assert_eq!(
                fixture.context.get_type_from_type_node(annotation).unwrap(),
                type_
            );
            assert_eq!(
                assert_date_union_identity(&mut fixture, Some(&globals)),
                union,
            );
            assert_eq!(
                (
                    fixture.context.store().type_len(),
                    fixture.context.store().symbol_len(),
                    fixture.context.store().signature_len(),
                    fixture.context.store().checker_link_allocated_lengths(),
                ),
                before,
            );
            if annotation_text == "string[]" {
                let store = fixture.context.store_mut_for_test();
                let number = store.intrinsic_bootstrap().unwrap().number_type;
                let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
                let before = (
                    store.type_len(),
                    store.symbol_len(),
                    store.signature_len(),
                    store.checker_link_allocated_lengths(),
                );
                assert!(
                    store
                        .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
                        .is_err()
                );
                assert_eq!(
                    (
                        store.type_len(),
                        store.symbol_len(),
                        store.signature_len(),
                        store.checker_link_allocated_lengths(),
                    ),
                    before,
                );
                let wrong_array = store
                    .create_canonical_array_type(&globals, number, false)
                    .unwrap();
                let literal_clone = store.create_array_literal_type(&globals, type_).unwrap();
                assert_ne!(literal_clone, type_);
                assert_eq!(
                    store
                        .canonical_array_reference(&globals, literal_clone)
                        .unwrap()
                        .unwrap()
                        .base_type,
                    type_,
                );
                let original = store.type_node_links(annotation).cloned().unwrap();
                for wrong_type in [wrong_array, literal_clone] {
                    assert!(store.set_type_node_links(
                        annotation,
                        TypeNodeLinks {
                            resolved_type: Some(wrong_type),
                            ..TypeNodeLinks::default()
                        },
                    ));
                    let before = (
                        store.type_len(),
                        store.symbol_len(),
                        store.signature_len(),
                        store.checker_link_allocated_lengths(),
                    );
                    for _ in 0..2 {
                        assert!(
                            store
                                .expression_union_type_with_global_types(
                                    &globals,
                                    &[fixture.type_, undefined],
                                    UnionReduction::Literal,
                                )
                                .is_err()
                        );
                    }
                    assert_eq!(
                        (
                            store.type_len(),
                            store.symbol_len(),
                            store.signature_len(),
                            store.checker_link_allocated_lengths(),
                        ),
                        before,
                    );
                }
                assert!(store.set_type_node_links(annotation, original));
                assert_eq!(
                    assert_date_union_identity(&mut fixture, Some(&globals)),
                    union
                );
            } else {
                let store = fixture.context.store_mut_for_test();
                let TypeData::Interface(interface) =
                    store.type_payload(fixture.type_).unwrap().data()
                else {
                    panic!("Date must retain its declared interface identity")
                };
                assert!(interface.base_types_resolved && interface.declared_members_resolved);
                let original = interface.reference.object.structured.clone();
                let mut missing = original.properties.clone().unwrap();
                assert!(missing.contains(&label));
                missing.retain(|member| *member != label);
                assert!(store.set_structured_type_members(
                    fixture.type_,
                    original.members,
                    Some(missing),
                    None,
                    None,
                    None,
                ));
                let before = (
                    store.type_len(),
                    store.symbol_len(),
                    store.signature_len(),
                    store.checker_link_allocated_lengths(),
                );
                let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
                for _ in 0..2 {
                    assert!(
                        store
                            .expression_union_type_with_global_types(
                                &globals,
                                &[fixture.type_, undefined],
                                UnionReduction::Literal,
                            )
                            .is_err()
                    );
                }
                assert_eq!(
                    (
                        store.type_len(),
                        store.symbol_len(),
                        store.signature_len(),
                        store.checker_link_allocated_lengths(),
                    ),
                    before,
                );
                assert!(store.set_structured_type_members(
                    fixture.type_,
                    original.members,
                    original.properties,
                    None,
                    None,
                    None,
                ));
                assert_eq!(
                    assert_date_union_identity(&mut fixture, Some(&globals)),
                    union,
                );
            }
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)] // Check both callable edge kinds and a corrupt signature.
    fn date_unions_keep_declared_method_provider_edges() {
        use crate::semantic::bootstrap::LiteralTypeCacheError;

        let library = parse_source_file(&format!(
            "{DATE_UNION_LIBRARY} interface Array<T> {{}} interface ReadonlyArray<T> {{}}",
        ));
        for (method_source, parameter_array) in [
            ("toFixed(values: string[]): number;", true),
            ("toFixed(value: number): string[];", false),
        ] {
            let augmentation = parse_source_file(&format!(
                "{DATE_UNION_AUGMENTATION} interface Date {{ {method_source} }}",
            ));
            let mut fixture = date_union_fixture(&library, &augmentation, true);
            let globals = fixture.context.global_types().clone();
            let union = assert_date_union_identity(&mut fixture, Some(&globals));
            let store = fixture.context.store();
            let method = store
                .symbol(fixture.date)
                .and_then(ts_binder::semantic::Symbol::members)
                .and_then(|members| store.symbol_table(members))
                .and_then(|members| members.get_source("toFixed"))
                .unwrap();
            let callable = fixture
                .context
                .artifact_interface_method_type(method)
                .unwrap();
            let store = fixture.context.store();
            let [signature] = store
                .type_payload(callable)
                .and_then(|record| record.data().structured())
                .and_then(|structured| structured.signatures.as_deref())
                .unwrap()
            else {
                panic!("toFixed must keep its source signature")
            };
            let signature = *signature;
            let signature_record = store.signature(signature).unwrap();
            let return_type = signature_record.resolved_return_type().unwrap();
            let array_type = if parameter_array {
                let [parameter] = signature_record.parameters() else {
                    panic!("toFixed must keep its source parameter")
                };
                store
                    .value_symbol_links(*parameter)
                    .unwrap()
                    .resolved_type
                    .unwrap()
            } else {
                return_type
            };
            assert_eq!(
                store
                    .canonical_array_reference(&globals, array_type)
                    .unwrap()
                    .unwrap()
                    .element_type,
                store.intrinsic_bootstrap().unwrap().string_type,
            );
            assert_eq!(
                assert_date_union_identity(&mut fixture, Some(&globals)),
                union,
            );
            let store = fixture.context.store_mut_for_test();
            let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
            let snapshot = |store: &CanonicalTypeMapperStore| {
                (
                    store.type_len(),
                    store.symbol_len(),
                    store.signature_len(),
                    store.mapper_len(),
                    store.index_info_len(),
                    store.checker_link_allocated_lengths(),
                )
            };
            let before = snapshot(store);
            for _ in 0..2 {
                assert_eq!(
                    store.expression_union_type(
                        &[fixture.type_, undefined],
                        UnionReduction::Literal,
                    ),
                    Err(LiteralTypeCacheError::UnsupportedUnionConstituent(
                        array_type
                    )),
                );
                assert_eq!(snapshot(store), before);
            }
            let boolean = store.intrinsic_bootstrap().unwrap().boolean_type;
            assert!(store.set_signature_resolved_return_type(signature, Some(boolean)));
            let invalid = LiteralTypeCacheError::InvalidCachedUnion(fixture.type_);
            assert_eq!(
                store.expression_union_type_with_global_types(
                    &globals,
                    &[fixture.type_, undefined],
                    UnionReduction::Literal,
                ),
                Err(invalid),
            );
            assert_eq!(snapshot(store), before);
            assert!(store.set_signature_resolved_return_type(signature, Some(return_type)));
            assert_eq!(
                assert_date_union_identity(&mut fixture, Some(&globals)),
                union,
            );
            assert!(fixture.context.diagnostics().is_empty());
        }
    }

    #[test]
    #[allow(clippy::too_many_lines)] // A nested cache error must not hide the reachable array.
    fn date_unions_reject_nested_member_list_poison_without_hiding_array_capability() {
        use crate::semantic::bootstrap::LiteralTypeCacheError;

        let library = parse_source_file(&format!(
            "{DATE_UNION_LIBRARY} interface Array<T> {{}} interface ReadonlyArray<T> {{}} \
             interface Holder {{ readonly date: Date; }} declare let holder: Holder;",
        ));
        let augmentation = parse_source_file(&format!(
            "{DATE_UNION_AUGMENTATION} interface Date {{ readonly label: string[]; }}",
        ));
        let mut fixture = date_union_fixture(&library, &augmentation, true);
        let globals = fixture.context.global_types().clone();
        let store = fixture.context.store();
        let holder_annotation = store
            .symbol_table(store.intrinsic_bootstrap().unwrap().globals)
            .and_then(|table| table.get_source("holder"))
            .and_then(|symbol| store.symbol(symbol))
            .and_then(ts_binder::semantic::Symbol::value_declaration)
            .and_then(|declaration| store.source_direct_type_annotation(declaration))
            .unwrap();
        let holder = fixture
            .context
            .get_type_from_type_node(holder_annotation)
            .unwrap();
        let store = fixture.context.store_mut_for_test();
        let label = store
            .symbol(fixture.date)
            .and_then(ts_binder::semantic::Symbol::members)
            .and_then(|table| store.symbol_table(table))
            .and_then(|table| table.get_source("label"))
            .unwrap();
        let array = store
            .value_symbol_links(label)
            .unwrap()
            .resolved_type
            .unwrap();
        assert_eq!(
            store
                .canonical_array_reference(&globals, array)
                .unwrap()
                .unwrap()
                .element_type,
            store.intrinsic_bootstrap().unwrap().string_type,
        );
        let TypeData::Interface(interface) = store.type_payload(fixture.type_).unwrap().data()
        else {
            panic!("Date must retain its interface identity")
        };
        assert!(interface.base_types_resolved && interface.declared_members_resolved);
        let original = interface.reference.object.structured.clone();
        let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
        let types = [holder, undefined];
        let union = store
            .expression_union_type_with_global_types(&globals, &types, UnionReduction::Literal)
            .unwrap();
        let counts = |store: &CanonicalTypeMapperStore| {
            (
                store.type_len(),
                store.symbol_len(),
                store.signature_len(),
                store.mapper_len(),
                store.index_info_len(),
                store.checker_link_allocated_lengths(),
            )
        };
        let before = counts(store);
        assert_eq!(
            store.expression_union_type(&types, UnionReduction::Literal),
            Err(LiteralTypeCacheError::UnsupportedUnionConstituent(array)),
        );
        assert_eq!(counts(store), before);
        let mut missing = original.properties.clone().unwrap();
        assert!(missing.contains(&label));
        missing.retain(|member| *member != label);
        assert!(store.set_structured_type_members(
            fixture.type_,
            original.members,
            Some(missing),
            None,
            None,
            None,
        ));
        for _ in 0..2 {
            assert_eq!(
                store.expression_union_type(&types, UnionReduction::Literal),
                Err(LiteralTypeCacheError::UnsupportedUnionConstituent(
                    fixture.type_
                )),
            );
            assert_eq!(
                store.expression_union_type_with_global_types(
                    &globals,
                    &types,
                    UnionReduction::Literal,
                ),
                Err(LiteralTypeCacheError::UnsupportedUnionConstituent(
                    fixture.type_
                )),
            );
            assert_eq!(counts(store), before);
        }
        assert!(store.set_structured_type_members(
            fixture.type_,
            original.members,
            original.properties,
            None,
            None,
            None,
        ));
        assert_eq!(
            store.expression_union_type_with_global_types(
                &globals,
                &types,
                UnionReduction::Literal
            ),
            Ok(union),
        );
        assert_eq!(
            store.expression_union_type(&types, UnionReduction::Literal),
            Err(LiteralTypeCacheError::UnsupportedUnionConstituent(array)),
        );
        assert_eq!(counts(store), before);
    }

    #[test]
    fn date_unions_preserve_published_source_index_interface_array_checks() {
        let library = parse_source_file(&format!(
            "{DATE_UNION_LIBRARY} interface Indexed {{ [index: number]: string; }} \
             interface IndexHolder {{ readonly value: Indexed; }} \
             declare let indexHolder: IndexHolder;",
        ));
        let augmentation = parse_source_file(DATE_UNION_AUGMENTATION);
        let mut fixture = date_union_fixture(&library, &augmentation, true);
        let globals = fixture.context.global_types().clone();
        let store = fixture.context.store();
        let annotation = store
            .symbol_table(store.intrinsic_bootstrap().unwrap().globals)
            .and_then(|table| table.get_source("indexHolder"))
            .and_then(|symbol| store.symbol(symbol))
            .and_then(ts_binder::semantic::Symbol::value_declaration)
            .and_then(|declaration| store.source_direct_type_annotation(declaration))
            .unwrap();
        let holder = fixture.context.get_type_from_type_node(annotation).unwrap();
        let store = fixture.context.store_mut_for_test();
        let [property] = store
            .type_payload(holder)
            .and_then(|record| record.data().structured())
            .and_then(|structured| structured.properties.as_deref())
            .unwrap()
        else {
            panic!("IndexHolder must publish its source property")
        };
        let indexed = store
            .value_symbol_links(*property)
            .and_then(|links| links.resolved_type)
            .unwrap();
        let TypeData::Interface(interface) = store.type_payload(indexed).unwrap().data() else {
            panic!("Indexed must retain its interface identity")
        };
        assert!(interface.base_types_resolved && interface.declared_members_resolved);
        let [index] = interface.declared_index_infos.as_deref().unwrap() else {
            panic!("Indexed must publish its source index signature")
        };
        let index = store.index_info(*index).unwrap();
        assert_eq!(
            index.key_type(),
            store.intrinsic_bootstrap().unwrap().number_type
        );
        assert_eq!(
            index.value_type(),
            store.intrinsic_bootstrap().unwrap().string_type
        );
        assert!(matches!(
            validate_resolved_declared_property_type_graph(store, indexed),
            DeclaredPropertyTypeGraphValidation::Opaque,
        ));
        let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
        let mut types = [holder, undefined];
        types.sort_unstable();
        let union = store
            .expression_union_type(&types, UnionReduction::Literal)
            .unwrap();
        assert_eq!(
            store.validate_canonical_union_metadata(union, &types),
            Ok(())
        );
        let before = (
            store.type_len(),
            store.symbol_len(),
            store.signature_len(),
            store.mapper_len(),
            store.index_info_len(),
            store.checker_link_allocated_lengths(),
        );
        for _ in 0..2 {
            assert_eq!(store.validate_cached_array_capability(indexed), Ok(()));
            assert_eq!(
                store.expression_union_type(&types, UnionReduction::Literal),
                Ok(union),
            );
            assert_eq!(
                store.expression_union_type_with_global_types(
                    &globals,
                    &types,
                    UnionReduction::Literal
                ),
                Ok(union),
            );
            assert_eq!(
                (
                    store.type_len(),
                    store.symbol_len(),
                    store.signature_len(),
                    store.mapper_len(),
                    store.index_info_len(),
                    store.checker_link_allocated_lengths(),
                ),
                before,
            );
        }
    }

    #[test]
    fn date_unions_keep_cold_and_warm_identity_without_demanding_sibling_methods() {
        let library = parse_source_file(DATE_UNION_LIBRARY);
        let augmentation = parse_source_file(DATE_UNION_AUGMENTATION);
        let mut fixture = date_union_fixture(&library, &augmentation, true);
        let store = fixture.context.store_mut_for_test();
        assert!(store.source_merged_symbol_declarations_match(fixture.date));
        assert!(store.value_symbol_links(fixture.marker).is_none());
        assert!(store.value_symbol_links(fixture.sibling).is_none());
        let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
        let null = store.intrinsic_bootstrap().unwrap().null_type;
        let signatures = store.signature_len();
        let symbols = store.symbol_len();
        let optional = store
            .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
            .unwrap();
        let nullable = store
            .expression_union_type(&[fixture.type_, null], UnionReduction::Literal)
            .unwrap();
        assert_eq!(store.signature_len(), signatures);
        assert_eq!(store.symbol_len(), symbols);
        assert!(store.value_symbol_links(fixture.marker).is_none());
        assert!(store.value_symbol_links(fixture.sibling).is_none());
        assert!(store.value_symbol_links(fixture.date).is_none());
        publish_date_union_marker(&mut fixture);
        let store = fixture.context.store_mut_for_test();
        assert!(store.value_symbol_links(fixture.sibling).is_none());
        let before = (
            store.type_len(),
            store.signature_len(),
            store.symbol_len(),
            store.mapper_len(),
            store.checker_link_allocated_lengths(),
        );
        assert_eq!(
            store.expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal),
            Ok(optional)
        );
        assert_eq!(
            store.expression_union_type(&[fixture.type_, null], UnionReduction::Literal),
            Ok(nullable)
        );
        assert_eq!(
            (
                store.type_len(),
                store.signature_len(),
                store.symbol_len(),
                store.mapper_len(),
                store.checker_link_allocated_lengths(),
            ),
            before
        );
        assert!(store.value_symbol_links(fixture.sibling).is_none());
        assert!(store.value_symbol_links(fixture.date).is_none());
        let TypeData::Interface(interface) = store.type_payload(fixture.type_).unwrap().data()
        else {
            panic!("Date must retain its declared interface identity")
        };
        assert!(!interface.declared_members_resolved);
    }

    #[test]
    fn date_unions_reject_forged_owners_and_poisoned_method_caches_before_writes() {
        let library = parse_source_file(DATE_UNION_LIBRARY);
        let augmentation = parse_source_file(DATE_UNION_AUGMENTATION);
        let mut fixture = date_union_fixture(&library, &augmentation, true);
        publish_date_union_marker(&mut fixture);
        let store = fixture.context.store_mut_for_test();
        let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
        let globals = store.intrinsic_bootstrap().unwrap().globals;
        let union = store
            .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
            .unwrap();
        let original = store.symbol(fixture.date).unwrap();
        let original_flags = original.flags();
        let declarations = original.declarations().unwrap().to_vec();
        let value_declaration = original.value_declaration();
        let mut copied = SymbolData::new(original.flags(), original.name().to_owned());
        copied.declarations = Some(declarations.clone());
        copied.value_declaration = value_declaration;
        copied.members = original.members();
        let forged = store.alloc_symbol(copied).unwrap();
        assert!(store.set_type_symbol(fixture.type_, Some(forged)));
        assert!(store.set_declared_type_links(
            forged,
            crate::semantic::DeclaredTypeLinks {
                declared_type: Some(fixture.type_),
                ..crate::semantic::DeclaredTypeLinks::default()
            }
        ));
        assert_eq!(
            store.insert_symbol(globals, EscapedName::source("Date"), forged),
            Some(Some(fixture.date))
        );
        let snapshot = |store: &CanonicalTypeMapperStore| {
            (
                store.type_len(),
                store.signature_len(),
                store.symbol_len(),
                store.mapper_len(),
                store.checker_link_allocated_lengths(),
            )
        };
        let before = snapshot(store);
        assert!(!store.source_merged_symbol_declarations_match(forged));
        assert!(
            store
                .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
                .is_err()
        );
        assert_eq!(snapshot(store), before);
        assert!(store.set_type_symbol(fixture.type_, Some(fixture.date)));
        assert_eq!(
            store.insert_symbol(globals, EscapedName::source("Date"), fixture.date),
            Some(Some(forged))
        );
        assert_eq!(
            store.expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal),
            Ok(union)
        );

        assert!(store.set_symbol_flags(
            fixture.date,
            original_flags.without(SymbolFlags::FUNCTION_SCOPED_VARIABLE)
                | SymbolFlags::BLOCK_SCOPED_VARIABLE,
            CheckFlags::NONE,
        ));
        let before = snapshot(store);
        assert!(!store.source_merged_symbol_declarations_match(fixture.date));
        assert!(
            store
                .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
                .is_err()
        );
        assert_eq!(snapshot(store), before);
        assert!(store.set_symbol_flags(fixture.date, original_flags, CheckFlags::NONE));
        assert_eq!(
            store.expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal),
            Ok(union)
        );

        let shortened = declarations
            .iter()
            .copied()
            .filter(|node| node.file != FileId::new(9_951))
            .collect();
        assert!(store.set_symbol_declarations(fixture.date, Some(shortened), value_declaration));
        let before = snapshot(store);
        assert!(!store.source_merged_symbol_declarations_match(fixture.date));
        assert!(
            store
                .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
                .is_err()
        );
        assert_eq!(snapshot(store), before);
        assert!(store.set_symbol_declarations(fixture.date, Some(declarations), value_declaration));
        assert_eq!(
            store.expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal),
            Ok(union)
        );

        let original_links = store.value_symbol_links(fixture.marker).cloned().unwrap();
        assert!(store.set_value_symbol_links(fixture.marker, ValueSymbolLinks::default()));
        let before = snapshot(store);
        assert!(
            store
                .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
                .is_err()
        );
        assert_eq!(snapshot(store), before);
        assert!(store.set_value_symbol_links(fixture.marker, original_links));
        assert_eq!(
            store.expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal),
            Ok(union)
        );
    }

    #[test]
    fn date_unions_reject_duplicate_constructor_declarations_without_writes() {
        let library = parse_source_file(DATE_UNION_LIBRARY);
        let augmentation = parse_source_file(concat!(
            "interface Date { toJSON(key?: any): string; } ",
            "interface DateConstructor { new(value: string): Date; }",
        ));
        for warm in [false, true] {
            let mut fixture = date_union_fixture(&library, &augmentation, true);
            let store = fixture.context.store_mut_for_test();
            let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
            let constructor = store
                .symbol_table(store.intrinsic_bootstrap().unwrap().globals)
                .and_then(|globals| globals.get_source("DateConstructor"))
                .and_then(|symbol| store.get_merged_symbol(symbol))
                .unwrap();
            let declarations = store
                .symbol(constructor)
                .unwrap()
                .declarations()
                .unwrap()
                .to_vec();
            assert_eq!(declarations.len(), 2);
            assert_ne!(declarations[0], declarations[1]);
            let cached = warm.then(|| {
                store
                    .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
                    .unwrap()
            });
            assert!(store.set_symbol_declarations(
                constructor,
                Some(vec![declarations[0], declarations[0]]),
                None,
            ));
            let before = (
                store.type_len(),
                store.symbol_len(),
                store.signature_len(),
                store.mapper_len(),
                store.checker_link_allocated_lengths(),
            );
            assert!(!store.source_merged_symbol_declarations_match(constructor));
            assert!(matches!(
                validate_resolved_declared_property_type_graph(store, fixture.type_),
                DeclaredPropertyTypeGraphValidation::Malformed,
            ));
            assert!(
                store
                    .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
                    .is_err()
            );
            assert_eq!(
                (
                    store.type_len(),
                    store.symbol_len(),
                    store.signature_len(),
                    store.mapper_len(),
                    store.checker_link_allocated_lengths(),
                ),
                before
            );
            assert!(store.set_symbol_declarations(constructor, Some(declarations), None));
            let restored = store
                .expression_union_type(&[fixture.type_, undefined], UnionReduction::Literal)
                .unwrap();
            if let Some(cached) = cached {
                assert_eq!(restored, cached);
            }
        }
    }

    #[test]
    fn date_unions_accept_ordinary_owners_without_library_reclassification() {
        let library = parse_source_file(DATE_UNION_LIBRARY);
        let augmentation = parse_source_file(DATE_UNION_AUGMENTATION);
        let mut fixture = date_union_fixture(&library, &augmentation, false);
        let store = fixture.context.store_mut_for_test();
        let source = store
            .register_source_file(&library.arena, library.source_file, FileId::new(9_950))
            .unwrap();
        assert!(
            !store.register_source_file_facts(
                source,
                &date_union_file_facts(FileId::new(9_950), true)
            )
        );
        let declaration = store
            .symbol(fixture.date)
            .unwrap()
            .value_declaration()
            .unwrap();
        assert!(!store.source_is_default_library_declaration(declaration));
        assert!(!authenticated_default_library_interface_owner(
            store,
            fixture.date,
        ));
        assert!(authenticated_nongeneric_global_interface_owner(
            store,
            fixture.date,
        ));
        let undefined = store.intrinsic_bootstrap().unwrap().undefined_type;
        let mut constituents = [fixture.type_, undefined];
        constituents.sort_unstable();
        assert!(
            store
                .intrinsic_bootstrap()
                .unwrap()
                .cached_union_type(&constituents)
                .is_none()
        );
        let union = assert_date_union_identity_without_member_writes(&mut fixture);
        let store = fixture.context.store_mut_for_test();
        let before = (
            store.type_len(),
            store.signature_len(),
            store.symbol_len(),
            store.mapper_len(),
            store.index_info_len(),
            store.checker_link_allocated_lengths(),
        );
        for _ in 0..2 {
            assert_eq!(
                assert_date_union_identity_without_member_writes(&mut fixture),
                union,
            );
            let store = fixture.context.store_mut_for_test();
            assert_eq!(
                (
                    store.type_len(),
                    store.signature_len(),
                    store.symbol_len(),
                    store.mapper_len(),
                    store.index_info_len(),
                    store.checker_link_allocated_lengths(),
                ),
                before,
            );
            for symbol in [fixture.date, fixture.marker, fixture.sibling] {
                assert!(store.value_symbol_links(symbol).is_none());
            }
        }
    }

    #[test]
    fn merged_interface_methods_stay_unsupported_outside_default_library_math_random() {
        for (index, source) in [
            "interface Shared { random(): number } declare var Shared: Shared;",
            "interface Shared { max(...values: number[]): number } declare var Shared: Shared;",
            "interface Math { random(): number } declare var Math: Math;",
            "interface Math { random(value: number): number } declare var Math: Math;",
            concat!(
                "interface Date { toISOString(): string } ",
                "interface DateConstructor {} declare var Date: DateConstructor;",
            ),
            concat!(
                "interface Number { toFixed(fractionDigits?: number): string } ",
                "interface NumberConstructor {} declare var Number: NumberConstructor;",
            ),
            concat!(
                "interface String { toLowerCase(): string } ",
                "interface StringConstructor {} declare var String: StringConstructor;",
            ),
            concat!(
                "interface Object { toString(): string } ",
                "interface ObjectConstructor {} declare var Object: ObjectConstructor;",
            ),
            concat!(
                "interface Symbol { toString(): string; ",
                "[Symbol.toPrimitive](hint: string): symbol } ",
                "interface SymbolConstructor {} declare var Symbol: SymbolConstructor;",
            ),
            concat!(
                "interface Math { max(...values: number[]): number; random(): number } ",
                "declare var Math: Math;",
            ),
            concat!(
                "interface Math { hypot(...values: number[]): number; random(): number } ",
                "declare var Math: Math;",
            ),
        ]
        .into_iter()
        .enumerate()
        {
            let fixture = interface_fixture(source, 3_795 + u32::try_from(index).unwrap());
            let host = host(&fixture.parsed, &fixture.bound);
            let before = (
                fixture.store.type_len(),
                fixture.store.signature_len(),
                fixture.store.checker_link_allocated_lengths(),
            );

            assert!(matches!(
                plan_interface(&fixture.store, &host, fixture.symbol),
                Err(PropertyObjectError::UnsupportedMember {
                    kind: SyntaxKind::MethodSignature,
                    ..
                })
            ));
            assert_eq!(
                (
                    fixture.store.type_len(),
                    fixture.store.signature_len(),
                    fixture.store.checker_link_allocated_lengths(),
                ),
                before,
            );
        }
    }

